/* =============================================================================
   Atlas de Arquitecturas — js/content/swin.js
   Página de modelo: Swin Transformer (Liu et al., ICCV 2021, arXiv:2103.14030).
   Plantilla fija de 11 secciones (SPEC §5.3).
   Regla: ningún número de la arquitectura se escribe a mano. Formas, parámetros y
   MACs salen del calculador (bloques op/trace/params/flops/scaling/compare y
   cantidades {{config.ruta}}, SPEC §6.6). Los números de entrenamiento y los
   resultados citan paper y tabla. Sin DOM al cargar.
   ========================================================================== */
(function (root) {
  'use strict';
  const ATLAS = (root.ATLAS = root.ATLAS || {});

  // LaTeX dentro de HTML: String.raw para no duplicar barras invertidas.
  const R = String.raw;
  // Cantidades del calculador (SPEC §6.6). C = configuración canónica.
  const C = 'swin-t-224';
  const RN = 'resnet50-224';
  const VB = 'vit-b16-224';
  const qn = (path, cfg) => '{{' + (cfg || C) + '.' + path + '}}';
  const sh = (id, cfg) => qn('tensor.' + id + '.shape', cfg);   // 64×49×96
  const sy = (id, cfg) => qn('tensor.' + id + '.sym', cfg);     // n_W×M²×C
  const np = (id, cfg) => qn('node.' + id + '.params', cfg);    // parámetros del nodo (× repeat ya aplicado)
  const oq = (id, f, cfg) => qn('op.' + id + '.' + f, cfg);      // un op del calculador

  const PAPER = 'Liu et al., <i>Swin Transformer: Hierarchical Vision Transformer using Shifted Windows</i>, ICCV 2021, arXiv:2103.14030';
  const RESNET = 'He et al., <i>Deep Residual Learning for Image Recognition</i>, CVPR 2016, arXiv:1512.03385';
  const CONVNEXT = 'Liu et al., <i>A ConvNet for the 2020s</i>, CVPR 2022, arXiv:2201.03545';
  const V2 = 'Liu et al., <i>Swin Transformer V2: Scaling Up Capacity and Resolution</i>, CVPR 2022, arXiv:2111.09883';

  ATLAS.register({
    id: 'swin',
    kind: 'model',
    sections: [
      // ======================================================== 1
      {
        id: 'para-que',
        titleEn: 'What it is for',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`<b>En una frase:</b> Swin recibe una imagen de ${sh('x-img')} y devuelve <b>cuatro mapas de features</b>, a strides 4, 8, 16 y 32 (${sh('s1-out')}, ${sh('s2-out')}, ${sh('s3-out')}, ${sh('s4-out')} en Swin-T), exactamente las escalas que un FPN espera de una ResNet. Para clasificar, promedia el último mapa y lo pasa a una lineal: ${sh('logits')} logits.` },
          { t: 'p', html: R`Lo que lo hace posible es una sola restricción (${PAPER}): la self-attention se calcula <b>solo dentro de ventanas</b> de M×M = 7×7 = 49 tokens que no se solapan, y en el bloque siguiente las ventanas se <b>desplazan</b> media ventana para que la información cruce sus bordes. Con ventanas de tamaño fijo, el costo de la atención crece <b>lineal</b> con el número de tokens (H·W/16), no cuadrático; ojo, eso es cuadrático en el lado: duplicar el lado de la imagen da ×4. Y eso permite empezar con tokens de 4×4 píxeles (${qn('tokens')} tokens a 224, 16 veces más que los ${qn('patches', VB)} patches de ViT-B/16) y bajar la resolución por etapas, como una CNN.` },
          { t: 'p', html: R`¿Por qué te lo van a preguntar? Porque Swin fue el puente entre las dos familias: el primer Transformer que se usó como <b>backbone de detección y segmentación</b> sin trucos, cambiando la ResNet de un Mask R-CNN o de un UperNet por Swin y ganando varios puntos (<a href="#swin.puente">puente</a>). Hoy sigue dentro de detectores de vocabulario abierto como <a href="#grounding-dino">Grounding DINO</a> (Swin-T) y es la referencia contra la que se comparan ConvNeXt, Hiera y ViTDet.` },
          { t: 'table', caption: 'Cuándo sí y cuándo no', head: ['Situación', '¿Swin?', 'Por qué'], rows: [
            ['Backbone para detección, segmentación de instancias o semántica (FPN, Mask R-CNN, UperNet, DINO, Mask2Former)', 'Sí', 'Da los cuatro mapas C2–C5 que esos cuellos esperan, con costo lineal en el número de píxeles (H·W) para M fijo.'],
            ['Imágenes grandes (800–1333 px en COCO, 512 px en ADE20K) con objetos de tamaños muy distintos', 'Sí', 'Stride 4 en el primer stage para objetos chicos; stride 32 para contexto.'],
            ['Clasificación de ImageNet a 224 con una receta tipo DeiT', 'Sí, pero ya no es lo único', 'Le gana a DeiT a costo parecido; ConvNeXt lo iguala con convoluciones puras (<a href="#swin.fallas">fallas</a>).'],
            ['Encoder de imagen de un VLM o de un modelo tipo CLIP', 'Normalmente no', 'Los VLMs quieren una secuencia plana de tokens y checkpoints contrastivos enormes: eso es ViT (<a href="#vit">ViT</a>, <a href="#clip">CLIP</a>, <a href="#llava">LLaVA</a>).'],
            ['Preentrenamiento autosupervisado tipo MAE (descartar 75 % de los tokens)', 'Con cuidado', 'Las ventanas necesitan la cuadrícula completa; quitar tokens rompe la partición. Hiera y SimMIM resuelven esto de formas distintas (<a href="#swin.variantes">variantes</a>).'],
            ['Edge con runtimes que no soportan bien <code>roll</code>, reshapes de 6 ejes o máscaras', 'Mide antes', 'Los MACs son los de una ResNet-50, pero las operaciones de memoria (partición, desplazamiento) pesan en latencia; una CNN es más fácil de desplegar.'],
          ] },
          { t: 'callout', kind: 'interview', html: R`<p>"Swin is a hierarchical vision transformer. It computes self-attention inside non-overlapping 7-by-7 windows, which makes attention cost linear in the number of tokens for a fixed window size, and it shifts the windows by half a window in every other block so information flows across window borders. Patch merging halves the resolution between stages, so it outputs feature maps at strides 4 to 32, like a ResNet, and drops into FPN-based detectors."</p>` },
        ],
      },

      // ======================================================== 2
      {
        id: 'puente',
        titleEn: 'Bridge from what you know',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`<b>Swin = un ViT con la jerarquía de una CNN.</b> Empieza por lo que ya conoces. ResNet-50 lleva la imagen de ${sh('x-img', RN)} a cuatro mapas: C2 ${sh('c2', RN)}, C3 ${sh('c3', RN)}, C4 ${sh('c4', RN)} y C5 ${sh('c5', RN)}. Strides 4, 8, 16 y 32. Swin-T produce <b>las mismas cuatro resoluciones</b>: ${sh('s1-out')}, ${sh('s2-out')}, ${sh('s3-out')} y ${sh('s4-out')}. Cambian los canales (96 → 768 en vez de 256 → 2048) y cambia cómo se mezcla la información dentro de cada stage. La geometría es idéntica, y por eso Swin entra en cualquier detector que ya tenía una ResNet.` },
          { t: 'compare', models: [RN, C], rows: ['params', 'macs', 'res'], caption: 'ResNet-50 vs Swin-T a 224 (calculador): mismo orden de parámetros y de MACs' },
          { t: 'table', caption: 'ResNet-50 vs Swin-T: qué equivale y qué es nuevo', head: ['Concepto', 'ResNet-50 (lo que sabes)', 'Swin-T', '¿Nuevo?'], rows: [
            ['Entrada a la red (stride 4)', R`Stem conv 7×7 s2 + max-pool s2 → ${sh('pool-out', RN)}`, R`Patch partition + linear embedding = conv 4×4, stride 4, + LayerNorm → ${sh('x-patch-grid')}`, 'Equivale: un stem que deja stride 4'],
            ['Etapas', 'conv2_x … conv5_x: 3, 4, 6, 3 bottlenecks', 'Stages 1–4: 2, 2, 6, 2 bloques Swin (en pares W-MSA / SW-MSA)', 'Equivale 1:1 (mismas resoluciones; el stage 3 es el más profundo en ambos)'],
            ['Bajar resolución entre etapas', 'El primer bottleneck de conv3_x, conv4_x y conv5_x usa stride 2 (en torchvision, en su conv 3×3) y una proyección 1×1 s2 en el atajo', 'Patch merging: concatenar vecinos 2×2 (4C) → LN → lineal 4C → 2C', 'Equivale: "stride 2 y el doble de canales"'],
            ['Mezcla espacial', 'Conv 3×3: pesos fijos, vecindad de 3×3', 'Self-attention dentro de una ventana de 7×7: pesos calculados por imagen (QKᵀ)', '<b>Nuevo</b>: la vecindad es local como en una conv, pero los pesos dependen del contenido'],
            ['Cómo crece el campo receptivo', 'Apilando convs 3×3 (+2 píxeles del mapa por capa)', 'Shifted windows: el bloque siguiente cruza los bordes de las ventanas; patch merging duplica el alcance en píxeles', '<b>Nuevo</b> el mecanismo; mismo efecto'],
            ['Mezcla de canales', 'Convs 1×1 del bottleneck', 'MLP por token, C → 4C → C', 'Equivale (MLP por token = conv 1×1)'],
            ['Posición', 'Implícita (kernel + padding)', 'Relative position bias: un escalar aprendido por desplazamiento relativo dentro de la ventana, sumado a QKᵀ', '<b>Nuevo</b> frente a ResNet; distinto de las posiciones absolutas de ViT'],
            ['Normalización', 'BatchNorm', 'LayerNorm (pre-LN, como ViT)', 'Cambia'],
            ['Cabeza', 'GAP → FC 2048 → 1000', 'LN → GAP → lineal 768 → 1000 (sin CLS)', 'Equivale'],
          ] },
          { t: 'p', html: R`Si vienes de YOLO: los cuatro mapas de Swin están en los niveles de stride que YOLO llama P2–P5 (4, 8, 16, 32); en la nomenclatura del FPN son las entradas C2–C5 y el cuello produce P2–P5. Un FPN o un PAN toma los tres últimos (o los cuatro) igual que de un CSPDarknet. La diferencia con <a href="#vit">ViT</a>, que vive siempre en stride 16 (el nivel 4), es justo lo que hace a Swin útil para objetos chicos.` },

          { t: 'h3', text: 'Frente a ViT: lo que cambia, con números' },
          { t: 'p', html: R`ViT-B/16 hace atención <b>global</b>: cada uno de sus ${qn('tokens', VB)} tokens mira a todos, en todas las capas. Eso cuesta N² por capa, y es tolerable solo porque los patches de 16×16 dejan pocos tokens. Swin quiere tokens de 4×4 píxeles para tener un mapa de stride 4: a 224 son ${qn('tokens')} tokens. Con atención global, el stage 1 tendría una matriz de ${qn('tokens')} × ${qn('tokens')} por cabeza: ${qn('metrics.s1GlobalScoreMacs')} MACs solo en QKᵀ y A·V, por bloque. Con ventanas de 7×7 son ${qn('metrics.s1ScoreMacs')}, ${qn('metrics.s1GlobalToWindow')} veces menos (= N/M², el número de ventanas). Esa es la idea entera.` },
          { t: 'table', caption: 'ViT-B/16 vs Swin-T: qué cambia (cuentas en costo)', head: ['', 'ViT-B/16 @ 224', 'Swin-T @ 224'], rows: [
            ['Tamaño del token', '16×16 píxeles', '4×4 píxeles (el stage 1); 32×32 en el stage 4'],
            ['Resolución a lo largo de la red', R`Constante: ${sh('x0', VB)}`, R`Pirámide: ${sh('s1-out')} → … → ${sh('s4-out')}`],
            ['Alcance de la atención', 'Global: todos con todos', 'Ventana de M×M = 49 tokens; el shift conecta ventanas vecinas'],
            ['Costo de QKᵀ y A·V', R`Cuadrático en tokens: 2N²D por capa`, R`Lineal en tokens: 2M²NC por bloque (M fijo)`],
            ['Posición', R`Absoluta, aprendida: tabla de ${sh('x0', VB)}`, 'Relativa: tabla de (2M−1)² = 169 escalares por cabeza, sumada a QKᵀ'],
            ['Token de clase', 'CLS', 'No hay: global average pooling'],
            ['Parámetros / MACs (calculador)', R`${qn('params.totalM', VB)} / ${qn('macs.totalG', VB)}`, R`${qn('params.totalM')} / ${qn('macs.totalG')}`],
          ] },
          { t: 'callout', kind: 'trap', title: '"Swin es una CNN disfrazada"', html: R`<p>No. Tiene la <b>geometría</b> de una CNN (stages, strides, campo receptivo local que crece), pero la mezcla espacial es atención: los pesos con los que un token combina a sus 48 vecinos de ventana se calculan para cada imagen. Una conv 7×7 depthwise (ConvNeXt) aplica los mismos 49 pesos en todas las posiciones. Y al revés, tampoco es "un ViT con menos tokens": los tokens de stride 4 y el patch merging le dan una pirámide que un ViT plano no tiene.</p>` },

          { t: 'h3', text: 'Por qué entra directo en un detector' },
          { t: 'p', html: R`Un FPN necesita mapas a strides 8, 16 y 32 (y a veces 4) con canales fijos por nivel: Swin los da sin adaptación, como la ResNet que reemplaza. El paper lo probó exactamente así: misma receta y mismos frameworks, cambiando solo el backbone. En COCO con Cascade Mask R-CNN, ResNet-50 llega a 46.3 AP<sup>box</sup> y Swin-T a 50.5, con 82 M vs 86 M parámetros en el detector completo y 739 vs 745 "GFLOPs" (Tabla 2(a)); la mejora se repite con ATSS, RepPoints v2 y Sparse R-CNN. En segmentación semántica (ADE20K), UperNet con Swin-T llega a 46.1 mIoU (Tabla 3).` },
          { t: 'callout', kind: 'note', html: R`<p>Detalle de implementación que pregunta quien ya integró Swin en mmdetection: el backbone de detección agrega una <b>LayerNorm por cada salida</b> (una por stage), y cada stage se reacomoda de tokens <code>N×C</code> a mapa <code>C×H×W</code> antes del FPN. En clasificación solo existe la LN final.</p>` },
          { t: 'callout', kind: 'connect', html: R`<p>Todo lo que pasa dentro de una ventana (Q, K, V, cabezas, softmax, A·V, residuales, pre-LN) es lo del <a href="#repaso-atencion">repaso de atención</a> y de <a href="#vit.operaciones">ViT</a>, aplicado a secuencias de 49 tokens. Lo nuevo de esta página son cuatro piezas: la partición en ventanas, el desplazamiento cíclico con su máscara, el relative position bias y el patch merging.</p>` },
        ],
      },

      // ======================================================== 3
      {
        id: 'diagrama',
        titleEn: 'Block diagram',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`El diagrama general es una CNN leída de arriba abajo: <b>patch partition + linear embedding</b> (stride 4), cuatro <b>stages</b> separados por <b>patch merging</b> (cada uno ÷2 la resolución y ×2 los canales), y la cabeza (LN → promedio → lineal). Cada stage es una pila de <b>pares</b> de bloques: el primero con ventanas regulares (W-MSA), el segundo con ventanas desplazadas (SW-MSA). Abre un stage para ver el par, y abre la atención de cada bloque para ver la partición, el bias relativo, el desplazamiento cíclico y la máscara. Usa "Recorrido" para seguir los números.` },
          { t: 'archdiagram', diagram: 'swin-overview', walk: 'forward', wide: true, caption: R`Swin-T @ 224: ${sh('x-img')} → tokens de 4×4 (${qn('tokens')}) → 4 stages a strides 4, 8, 16, 32 → ${sh('logits')} logits. Las formas de las aristas salen del calculador.` },
          { t: 'p', html: R`Antes de las fórmulas, mira las ventanas. La visualización arranca con la cuadrícula ilustrativa de la Fig. 2 del paper (8×8 tokens, M = 4) y te deja pasar a la de cada stage real: el stage 1 es un mapa de ${sh('s1-out')} cortado en ventanas de 7×7 (64 ventanas). En el bloque siguiente las ventanas se corren ⌊M/2⌋ tokens en cada eje (3 con M = 7); sin truco, eso daría ventanas de tamaños distintos en los bordes. El desplazamiento cíclico enrolla el mapa para que siga habiendo 64 ventanas de 7×7, y una máscara impide que se mezclen tokens que en la imagen original no eran vecinos.` },
          { t: 'viz', kind: 'shifted-windows', params: { config: C, grid: 'demo', mode: 'shifted' }, caption: 'Ventanas regulares vs desplazadas, el desplazamiento cíclico, las 9 regiones y la máscara de atención. La cuadrícula 8×8 es ilustrativa (Fig. 2 del paper); las de cada stage y sus números salen del calculador.' },
          { t: 'callout', kind: 'note', html: R`<p>Tres detalles del diagrama: (1) los bloques van <b>en pares</b> (W-MSA, luego SW-MSA), por eso las profundidades son pares (2, 2, 6, 2) y el stack se marca "× pares"; (2) en el stage 4 de Swin-T el mapa es de 7×7 = una sola ventana, así que el segundo bloque de ese stage, que en papel es SW-MSA, <b>no desplaza</b> (shift 0): es un W-MSA más (ver <a href="#swin.inferencia">inferencia</a>); (3) no hay token CLS ni position embedding absoluta: la posición entra como un bias dentro de la atención.</p>` },
        ],
      },

      // ======================================================== 4
      {
        id: 'operaciones',
        titleEn: 'Operations per block',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`Primero en palabras, con Swin-T a 224: ${sh('x-img')} → conv 4×4 s4 → ${sh('x-patch-grid')} → LN → ${sh('x-embed')} → stage 1 (2 bloques, forma constante) → patch merging → ${sh('m1-out')} → stage 2 → … → stage 4 ${sh('s4-out')} → LN → promedio → ${sh('pooled')} → ${sh('logits')}. Dentro de un bloque, la secuencia se corta en ventanas: ${sh('s1-b1-win')} (ventanas × tokens por ventana × canales), y cada cabeza ve ${sh('s1-b1-q')}. Ahora la notación del paper (§3.2, ec. 3): dos bloques consecutivos son` },
          { t: 'math', display: true, tex: R`\begin{aligned}
\hat{\mathbf{z}}^{l} &= \text{W-MSA}\big(\mathrm{LN}(\mathbf{z}^{l-1})\big) + \mathbf{z}^{l-1}, &
\mathbf{z}^{l} &= \mathrm{MLP}\big(\mathrm{LN}(\hat{\mathbf{z}}^{l})\big) + \hat{\mathbf{z}}^{l},\\
\hat{\mathbf{z}}^{l+1} &= \text{SW-MSA}\big(\mathrm{LN}(\mathbf{z}^{l})\big) + \mathbf{z}^{l}, &
\mathbf{z}^{l+1} &= \mathrm{MLP}\big(\mathrm{LN}(\hat{\mathbf{z}}^{l+1})\big) + \hat{\mathbf{z}}^{l+1}
\end{aligned}`, caption: 'Ecuación 3 de Liu et al. (2021): un par de bloques Swin. Es un bloque pre-LN de ViT con la atención global cambiada por atención en ventanas, regular y desplazada.' },
          { t: 'table', caption: 'Símbolos del paper ↔ símbolos de esta app', head: ['Paper', 'App', 'Qué es', 'Swin-T @ 224, stage 1'], rows: [
            ['h × w (patches)', R`h<sub>s</sub> × w<sub>s</sub>; N = h<sub>s</sub>w<sub>s</sub>`, 'alto y ancho del mapa de tokens del stage (¡en el paper h no son las cabezas!)', R`${qn('quantities.s1Res')}×${qn('quantities.s1Res')} (N = ${qn('quantities.s1Tokens')})`],
            ['C', R`C, 2C, 4C, 8C`, 'canales del stage 1; se duplican en cada patch merging', qn('cfg.C')],
            ['M', 'M', 'lado de la ventana, en tokens', qn('cfg.M')],
            ['d (query dim por cabeza)', R`d<sub>h</sub>`, 'ancho por cabeza; 32 en todos los stages', qn('quantities.dh')],
            ['heads', 'h', 'cabezas: 3, 6, 12, 24 (= C<sub>stage</sub>/32)', qn('quantities.s1Heads')],
            [R`—`, R`n<sub>W</sub> = N/M²`, 'ventanas por imagen en el stage', sy('s1-b1-win') + ' = ' + sh('s1-b1-win')],
          ] },
          { t: 'callout', kind: 'note', html: R`<p>Convención de formas (SPEC §6.2): sin batch, "tokens × canales". timm trabaja con el mapa en <code>B×H×W×C</code> (channels-last) entre bloques, y la partición apila las ventanas en el eje del batch: la entrada a la atención es <code>(B·n_W)×M²×C</code>. Por eso el kernel de atención es el mismo que el de ViT, solo que con "batch" ×64 y secuencias de 49.</p>` },

          { t: 'h3', text: 'Entrada: patch partition + linear embedding' },
          { t: 'op', block: 'patch-embed', model: 'swin', title: 'Patch partition + linear embedding (conv 4×4, stride 4, + LN)',
            tex: R`\mathbf{x}_p^i\in\mathbb{R}^{4\cdot 4\cdot 3 = 48},\quad i=1..\tfrac{H}{4}\cdot\tfrac{W}{4};\qquad \mathbf{z}^0 = \mathrm{LN}\big(\mathbf{x}_p\mathbf{E} + \mathbf{b}\big),\ \ \mathbf{E}\in\mathbb{R}^{48\times C}\ \equiv\ \mathrm{Conv2d}(3\!\to\!C,\ k{=}4,\ s{=}4)`,
            in: ['x-img'], out: ['x-patch-grid', 'x-embed'], params: true, flops: true,
            what: R`Igual que el patch embedding de ViT, pero con patches de 4×4: cada uno es un vector de 4·4·3 = 48 números proyectado a C. ${sh('x-img')} → ${sh('x-patch-grid')}. Después, una LayerNorm por token: ${sh('x-embed')}. El calculador deja los mapas como cuadrícula H×W×C (como timm); como secuencia serían ${qn('tokens')} tokens de C. El paper lo llama "patch partition" (cortar en 4×4) + "linear embedding" (proyectar a C); en código es una sola conv.`,
            why: R`Stride 4 es el stride del stem de una ResNet (conv 7×7 s2 + max-pool s2). Arrancar tan fino solo es viable porque la atención va a ser local: con atención global, ${qn('tokens')} tokens serían 16 veces los de ViT-B/16 y la matriz de atención, 256 veces más grande. A diferencia de ViT, aquí <b>no se suma ninguna position embedding</b> (el paper la probó: absoluta + relativa no mejora, Tabla 4).` },

          { t: 'h3', text: 'Un bloque con ventanas regulares (W-MSA)' },
          { t: 'p', html: R`Un bloque Swin es un bloque pre-LN de ViT donde la MSA global se cambia por atención en ventanas. Todo lo que sigue es el <b>bloque 1 del stage 1</b>; los demás stages son iguales con otros números (las formas de cada uno están en el trace). Las tablas de conteo de cada tarjeta son las de <b>un solo bloque</b> (el W-MSA del stage 1); el bloque SW-MSA tiene la misma forma y el mismo conteo, con pesos distintos.` },
          { t: 'op', block: 'w-ln1', model: 'swin', title: 'LayerNorm antes de la atención',
            tex: R`\mathrm{LN}(\mathbf{z}^{l-1}),\quad \text{sobre las } C \text{ componentes de cada token}`,
            in: ['x-embed'], out: ['s1-b1-ln1'], params: true,
            what: R`Igual que en ViT: cada token por separado, 2C parámetros. La entrada del primer bloque es la salida del patch embedding: ${sh('x-embed')} → ${sh('s1-b1-ln1')}.`,
            why: R`Pre-LN: el camino residual queda como identidad. Swin V2 cambiará justo esto para escalar a 3 mil millones de parámetros (<a href="#swin.variantes">variantes</a>).` },
          { t: 'op', block: 'partition', model: 'swin', diagram: 'swin-wmsa', title: 'Partición en ventanas',
            tex: R`\mathbb{R}^{h_s w_s\times C}\ \to\ \mathbb{R}^{h_s\times w_s\times C}\ \to\ \mathbb{R}^{n_W\times M^2\times C},\qquad n_W = \tfrac{h_s}{M}\cdot\tfrac{w_s}{M}`,
            in: ['s1-b1-ln1'], out: ['s1-b1-win'],
            what: R`Vuelve a poner la secuencia como mapa y la corta en ventanas de M×M que no se solapan: ${sh('s1-b1-ln1')} → ${sh('s1-b1-win')}. En el stage 1 de Swin-T son 8×8 = 64 ventanas de 49 tokens. Es un <code>view</code> + <code>permute</code> de 6 ejes: sin parámetros ni MACs.`,
            why: R`Convierte un problema de atención sobre ${qn('tokens')} tokens en 64 problemas independientes de 49 tokens, que se resuelven como un batch. Cada token solo puede mirar a los 49 de su ventana: la misma localidad que una conv 7×7, con pesos que dependen del contenido.` },
          { t: 'op', block: 'qkv', model: 'swin', diagram: 'swin-wmsa', title: 'Proyección Q, K, V por ventana',
            tex: R`[\,\mathbf{Q}\ \ \mathbf{K}\ \ \mathbf{V}\,] = \mathbf{X}_\text{win}\mathbf{W}_{qkv} + \mathbf{b}_{qkv},\quad \mathbf{W}_{qkv}\in\mathbb{R}^{C\times 3C};\qquad \mathbf{Q},\mathbf{K},\mathbf{V}\in\mathbb{R}^{n_W\times h\times M^2\times d_h}`,
            in: ['s1-b1-win'], out: ['s1-b1-qkv', 's1-b1-q', 's1-b1-k', 's1-b1-v'], params: true, flops: true,
            what: R`Una lineal C → 3C con bias, compartida por todas las ventanas: ${sh('s1-b1-win')} → ${sh('s1-b1-qkv')}, y se divide en h cabezas de d<sub>h</sub> = 32: Q, K y V quedan ${sh('s1-b1-q')}.`,
            why: R`Los mismos pesos en todas las ventanas: es la "compartición de pesos" de una conv, aplicada a las proyecciones. Las proyecciones son lineales en tokens y no cambian por usar ventanas: el ahorro está solo en QKᵀ y A·V.` },
          { t: 'op', block: 'scores', model: 'swin', diagram: 'swin-wmsa', title: 'Puntuaciones QKᵀ / √d dentro de cada ventana',
            tex: R`\mathbf{S} = \frac{\mathbf{Q}\mathbf{K}^\top}{\sqrt{d_h}}\ \in\ \mathbb{R}^{n_W\times h\times M^2\times M^2}`,
            in: ['s1-b1-q', 's1-b1-k'], out: ['s1-b1-scores', 's1-b1-scaled'], flops: true,
            what: R`Producto punto de cada consulta con las 49 claves de su ventana: ${sh('s1-b1-q')} · ${sh('s1-b1-k')}ᵀ → ${sh('s1-b1-scores')}. Una matriz de 49×49 por ventana y por cabeza.`,
            why: R`Con atención global serían ${qn('tokens')}×${qn('tokens')} por cabeza. En ventanas, cada token se compara con M² = 49 tokens en lugar de con N, y por eso el costo de este paso es N·M²·C en vez de N²·C.` },
          { t: 'op', block: 'bias', model: 'swin', diagram: 'swin-wmsa', title: 'Relative position bias',
            tex: R`\mathrm{Attention}(\mathbf{Q},\mathbf{K},\mathbf{V}) = \mathrm{SoftMax}\!\Big(\frac{\mathbf{Q}\mathbf{K}^\top}{\sqrt{d}} + \mathbf{B}\Big)\mathbf{V},\qquad \mathbf{B}\in\mathbb{R}^{M^2\times M^2},\ \ \mathbf{B}_{ij} = \hat{\mathbf{B}}\big[\Delta y_{ij}+M-1,\ \Delta x_{ij}+M-1\big],\ \ \hat{\mathbf{B}}\in\mathbb{R}^{(2M-1)\times(2M-1)}`,
            in: ['s1-b1-scaled'], out: ['s1-b1-biased'], params: true,
            what: R`A cada puntuación se le suma un escalar aprendido que depende <b>solo del desplazamiento relativo</b> entre la consulta i y la clave j dentro de la ventana: Δy, Δx ∈ [−(M−1), M−1], o sea (2M−1)² = 13² = 169 desplazamientos posibles. La tabla B̂ tiene 169 valores <b>por cabeza</b> (en el stage 1, 169 × 3); la matriz B de 49×49 se arma indexando B̂ con un índice fijo. ${sh('s1-b1-scaled')} → ${sh('s1-b1-biased')}.`,
            why: R`Es como decir "el vecino de arriba a la izquierda me importa tanto, independientemente de dónde esté la ventana": una noción de posición <b>invariante a traslación</b> dentro de la ventana, el tipo de sesgo que tiene una conv. Funciona mejor que las posiciones absolutas de ViT: 81.3 vs 80.5 top-1 en ImageNet y 50.5 vs 49.0 AP<sup>box</sup> en COCO (Tabla 4). La tabla B̂ es un <b>parámetro</b> (se entrena y se cuenta); el índice que la expande a 49×49 es un <b>buffer</b> (fijo, no se cuenta).` },
          { t: 'op', block: 'softmax', model: 'swin', diagram: 'swin-wmsa', title: 'Softmax por fila dentro de la ventana',
            tex: R`\mathbf{A} = \mathrm{softmax}_\text{fila}(\mathbf{S} + \mathbf{B})\ \in\ \mathbb{R}^{n_W\times h\times M^2\times M^2}`,
            in: ['s1-b1-biased'], out: ['s1-b1-attn'],
            what: R`Softmax sobre las 49 claves de cada fila: ${sh('s1-b1-biased')} → ${sh('s1-b1-attn')}. Cada fila (una consulta) queda como una distribución sobre los 49 tokens de su ventana. Es elementwise: sin parámetros y sin MACs de matmul.`,
            why: R`Mismo mecanismo que en ViT; solo cambia el largo de la fila (49 en lugar de ${qn('tokens', VB)}). Como cada fila solo ve su ventana, el softmax nunca reparte peso fuera de ella.` },
          { t: 'op', block: 'weighted-sum', model: 'swin', diagram: 'swin-wmsa', title: 'Suma ponderada A·V dentro de la ventana',
            tex: R`\mathbf{Z} = \mathbf{A}\mathbf{V}\ \in\ \mathbb{R}^{n_W\times h\times M^2\times d_h}`,
            in: ['s1-b1-attn', 's1-b1-v'], out: ['s1-b1-z-heads'], flops: true,
            what: R`Cada token se reemplaza por el promedio ponderado de los 49 valores de su ventana: ${sh('s1-b1-attn')} · ${sh('s1-b1-v')} → ${sh('s1-b1-z-heads')}. Cuesta lo mismo que QKᵀ: M²·d<sub>h</sub> MACs por consulta y cabeza.`,
            why: R`Aquí la información se mueve entre tokens, pero solo dentro de la ventana: sin el desplazamiento del bloque siguiente, un token nunca vería más allá de su ventana en todo el stage. QKᵀ y A·V juntos son el término 2M²NC de la ecuación 2.` },
          { t: 'op', block: 'proj', model: 'swin', diagram: 'swin-wmsa', title: 'Concatenar cabezas y proyección de salida',
            tex: R`\mathbf{O} = [\,\mathbf{Z}_1;\ \cdots;\ \mathbf{Z}_h\,]\,\mathbf{W}_O + \mathbf{b},\qquad \mathbf{W}_O\in\mathbb{R}^{C\times C}`,
            in: ['s1-b1-z-heads'], out: ['s1-b1-z', 's1-b1-proj'], params: true, flops: true,
            what: R`Une las cabezas, ${sh('s1-b1-z-heads')} → ${sh('s1-b1-z')}, y aplica una lineal C → C: ${sh('s1-b1-proj')}.`,
            why: R`Igual que W<sub>O</sub> en ViT: mezcla lo que encontraron las cabezas y vuelve al espacio del residual.` },
          { t: 'op', block: 'reverse', model: 'swin', diagram: 'swin-wmsa', title: 'Deshacer la partición',
            tex: R`\mathbb{R}^{n_W\times M^2\times C}\ \to\ \mathbb{R}^{h_s\times w_s\times C}\ \to\ \mathbb{R}^{h_s w_s\times C}`,
            in: ['s1-b1-proj'], out: ['s1-b1-unwin'],
            what: R`Vuelve a armar el mapa con las ventanas en su lugar: ${sh('s1-b1-proj')} → ${sh('s1-b1-unwin')}. Sin parámetros.`,
            why: R`El residual y el MLP trabajan por token, no por ventana: la partición es solo un "formato" para la atención.` },
          { t: 'op', block: 'w-res1', model: 'swin', title: 'Residual 1',
            tex: R`\hat{\mathbf{z}}^{l} = \text{W-MSA}\big(\mathrm{LN}(\mathbf{z}^{l-1})\big) + \mathbf{z}^{l-1}`,
            in: ['s1-b1-unwin', 'x-embed'], out: ['s1-b1-r1'],
            what: R`${sh('s1-b1-unwin')} + ${sh('x-embed')} (la entrada del bloque, antes de la LN) → ${sh('s1-b1-r1')}.`,
            why: R`Camino identidad, igual que en ResNet y ViT.` },
          { t: 'op', block: 'w-mlp', model: 'swin', title: 'MLP con GELU (C → 4C → C)',
            tex: R`\mathbf{z}^{l} = \mathrm{MLP}\big(\mathrm{LN}(\hat{\mathbf{z}}^{l})\big) + \hat{\mathbf{z}}^{l},\qquad \mathrm{MLP}(\mathbf{x}) = \mathrm{GELU}(\mathbf{x}\mathbf{W}_1+\mathbf{b}_1)\mathbf{W}_2+\mathbf{b}_2,\ \ \mathbf{W}_1\in\mathbb{R}^{C\times 4C}`,
            in: ['s1-b1-ln2'], out: ['s1-b1-u', 's1-b1-g', 's1-b1-f'], params: true, flops: true,
            what: R`Por token, como en ViT: ${sh('s1-b1-ln2')} → ${sh('s1-b1-u')} → GELU → ${sh('s1-b1-f')}. Razón de expansión α = 4 (§3.3). Antes va la LN 2 (2C parámetros, su propio nodo del diagrama) y después el residual 2: ${sh('s1-b1-f')} + ${sh('s1-b1-r1')} → ${sh('s1-b1-out')}. El conteo de esta tarjeta es solo el de las dos lineales.`,
            why: R`Es la mezcla de canales (las conv 1×1 de la ResNet) y, como en ViT, donde están la mayoría de los parámetros de cada bloque: 8C² del MLP contra 4C² de la atención. Las ventanas no lo tocan.` },

          { t: 'h3', text: 'El bloque siguiente: ventanas desplazadas (SW-MSA)' },
          { t: 'p', html: R`El problema de W-MSA: las ventanas son islas. Si todos los bloques usaran la misma partición, un token del borde de una ventana nunca vería al vecino que tiene al lado, en la ventana de junto, aunque estén a un píxel. La solución del paper (§3.2): en el bloque siguiente, mover la partición ⌊M/2⌋ = 3 tokens en cada eje. Las ventanas nuevas quedan a caballo entre cuatro ventanas viejas, y eso conecta a todas con sus vecinas.` },
          { t: 'op', block: 'shift', model: 'swin', diagram: 'swin-swmsa', title: 'Desplazamiento cíclico (cyclic shift)',
            tex: R`\mathbf{X}' = \mathrm{roll}\big(\mathbf{X},\ (-\lfloor M/2\rfloor,\ -\lfloor M/2\rfloor),\ \text{ejes } (h_s, w_s)\big)`,
            in: ['s1-b2-ln1'], out: ['s1-b2-shift'],
            what: R`Antes de partir en ventanas, enrolla el mapa 3 tokens hacia arriba y 3 a la izquierda (<code>torch.roll</code>): lo que sale por un borde entra por el opuesto. La forma no cambia: ${sh('s1-b2-ln1')} → ${sh('s1-b2-shift')}. Después se parte en ventanas regulares de 7×7, como en el bloque anterior.`,
            why: R`Desplazar la partición sin enrollar produciría ventanas de tamaños distintos en los bordes y más ventanas: de ⌈h/M⌉×⌈w/M⌉ a (⌈h/M⌉+1)×(⌈w/M⌉+1), es decir de 8×8 = 64 a 9×9 = 81 en el stage 1. Se podría rellenar con padding, pero cuesta más. Con el enrollado sigue habiendo exactamente <b>64 ventanas de 49 tokens</b> y el mismo kernel batched (Tabla 5: 755 vs 670 FPS en Swin-T con cyclic shift vs padding). Y el shift casi no cuesta: sin desplazamiento son 770 FPS.` },
          { t: 'op', block: 'mask', model: 'swin', diagram: 'swin-swmsa', title: 'Máscara de atención (por qué hace falta)',
            tex: R`\mathbf{A} = \mathrm{softmax}_\text{fila}\Big(\frac{\mathbf{Q}\mathbf{K}^\top}{\sqrt{d_h}} + \mathbf{B} + \mathbf{M}_\text{mask}\Big),\qquad (\mathbf{M}_\text{mask})_{ij} = \begin{cases}0 & \text{misma región}\\ -100 & \text{regiones distintas}\end{cases}`,
            in: ['s1-b2-biased'], out: ['s1-b2-masked'],
            what: R`El enrollado deja, en las ventanas del borde, tokens que en la imagen <b>no eran vecinos</b>: una fila del borde inferior pegada a una del borde superior. Cada token se etiqueta según la región de la que vino (son 9 regiones: 3 franjas por eje), y se suma −100 a las puntuaciones entre tokens de regiones distintas. Tras el softmax, esos pesos son ≈ 0. ${sh('s1-b2-biased')} → ${sh('s1-b2-masked')}. La máscara (una matriz de 49×49 por ventana, ${qn('quantities.s1Windows')} ventanas en el stage 1) depende solo de la geometría: se calcula una vez y es un buffer.`,
            why: R`Sin máscara, el cielo de la parte superior de la foto se mezclaría con el suelo de la parte inferior solo porque el enrollado los juntó: una conexión que no existe en la imagen. La implementación oficial usa −100 en lugar de −∞ (no da la razón): e⁻¹⁰⁰ ≈ 0 tras el softmax, así que el efecto es el mismo, y se evita operar con infinitos al sumar la máscara con el bias o en fp16. Aquí −∞ también funcionaría sin NaN, porque ninguna fila queda enmascarada entera: cada token comparte región al menos consigo mismo. Solo las ventanas de la última fila y de la última columna mezclan regiones (15 de las 64 en el stage 1); en las demás, la máscara es toda cero.` },
          { t: 'op', block: 'unshift', model: 'swin', diagram: 'swin-swmsa', title: 'Deshacer el desplazamiento',
            tex: R`\mathbf{X} = \mathrm{roll}\big(\mathbf{X}',\ (+\lfloor M/2\rfloor,\ +\lfloor M/2\rfloor)\big)`,
            in: ['s1-b2-unwin'], out: ['s1-b2-unshift'],
            what: R`Después de la atención y de deshacer la partición, enrolla en sentido contrario para que cada token vuelva a su posición: ${sh('s1-b2-unwin')} → ${sh('s1-b2-unshift')}. Luego residual, LN, MLP y residual, como en el bloque W-MSA.`,
            why: R`El residual suma la entrada original sin desplazar; si no se deshiciera el roll, se sumarían tokens de posiciones distintas.` },
          { t: 'callout', kind: 'trap', title: '"Las ventanas desplazadas se solapan"', html: R`<p>No. En cada bloque las ventanas forman una partición <b>sin solapamiento</b>: cada token está en exactamente una ventana. Lo que cambia entre bloques es <b>dónde</b> están los bordes. Por eso no es una "sliding window" (como SASA o una conv), donde cada token tiene su propia vecindad centrada: eso exige una vecindad distinta por consulta, accesos a memoria poco amigables y, según la Tabla 5, es mucho más lento (sliding window con kernel propio: 488 FPS en Swin-T vs 755 con shifted windows).</p>` },

          { t: 'h3', text: 'Patch merging: el stride 2 de Swin' },
          { t: 'op', block: 'merge1', model: 'swin', title: 'Patch merging (concat 2×2 → LN → lineal 4C → 2C, sin bias)',
            tex: R`\mathbf{x}' = \mathrm{LN}\big([\,\mathbf{x}_{2i,2j};\ \mathbf{x}_{2i+1,2j};\ \mathbf{x}_{2i,2j+1};\ \mathbf{x}_{2i+1,2j+1}\,]\big)\,\mathbf{W}_r,\qquad \mathbf{W}_r\in\mathbb{R}^{4C\times 2C}`,
            in: ['s1-out'], out: ['m1-concat', 'm1-ln', 'm1-out'], params: true, flops: true,
            what: R`Agrupa cada bloque de 2×2 tokens vecinos y concatena sus vectores: ${sh('s1-out')} → ${sh('m1-concat')} (4C canales, ¼ de los tokens). Normaliza con LN sobre los 4C y proyecta con una lineal <b>sin bias</b> a 2C: ${sh('m1-out')}. Los tres merges de Swin-T llevan 96 → 192 → 384 → 768 canales.`,
            why: R`Es exactamente la regla de una CNN al pasar de stage: resolución ÷2, canales ×2, así el costo por stage se mantiene parecido (tokens ÷4, C² ×4). Concatenar 2×2 y proyectar es una conv 2×2 con stride 2 escrita como reshape + lineal (con una LN en medio). La lineal no lleva bias porque la LN anterior ya tiene su β.` },
          { t: 'callout', kind: 'skip', html: R`<p><b>Sáltate esto:</b> en qué orden se concatenan los cuatro vecinos. La implementación original usa (0,0), (1,0), (0,1), (1,1). Las versiones nuevas de timm escriben la concatenación con un <code>reshape</code> + <code>permute</code> que conserva ese mismo orden, pero mueven el merging al <b>inicio</b> del stage siguiente en lugar del final del anterior. Los conteos no cambian; lo que cambia son las claves del state dict (<code>layers.i.downsample</code> pasa a <code>layers.i+1.downsample</code>), y timm las remapea al cargar los pesos originales.</p>` },

          { t: 'h3', text: 'Cabeza' },
          { t: 'op', block: 'final-ln', model: 'swin', title: 'LayerNorm final',
            tex: R`\mathrm{LN}(\mathbf{z}^{L})`,
            in: ['s4-out'], out: ['x-ln'], params: true,
            what: R`Normaliza los ${qn('quantities.s4Tokens')} tokens del stage 4: ${sh('s4-out')} → ${sh('x-ln')}.`,
            why: R`Igual que en ViT: necesaria en pre-LN porque el residual nunca se normalizó.` },
          { t: 'op', block: 'pool', model: 'swin', title: 'Global average pooling',
            tex: R`\mathbf{y} = \tfrac{1}{N_4}\textstyle\sum_{i} \mathrm{LN}(\mathbf{z}^{L})_i\ \in\ \mathbb{R}^{8C}`,
            in: ['x-ln'], out: ['pooled'],
            what: R`Promedio sobre los tokens: ${sh('x-ln')} → ${sh('pooled')}. Exactamente el GAP de una ResNet sobre su mapa de 7×7.`,
            why: R`Sin token CLS: con una pirámide, el CLS tendría que viajar por los merges y no aporta nada que el promedio no dé.` },
          { t: 'op', block: 'head', model: 'swin', title: 'Clasificador lineal',
            tex: R`\text{logits} = \mathbf{y}\,\mathbf{W}_\text{head} + \mathbf{b},\qquad \mathbf{W}_\text{head}\in\mathbb{R}^{8C\times K}`,
            in: ['pooled'], out: ['logits'], params: true, flops: true,
            what: R`Lineal 8C → K: ${sh('pooled')} → ${sh('logits')} (K = 1000, como timm <code>swin_tiny_patch4_window7_224</code>).`,
            why: R`Para detección se descartan LN final, pooling y cabeza: se usan los cuatro mapas de stage.` },

          { t: 'h3', text: 'El recorrido completo con números' },
          { t: 'p', html: R`Cada fila es un tensor en orden forward. El primer bloque de cada tipo aparece completo; los bloques repetidos se resumen. Fíjate en cómo los tokens bajan ×4 y los canales suben ×2 en cada patch merging, y en que el número de ventanas pasa de 64 a 16, 4 y 1. Toca una fila para resaltar el tensor en el diagrama.` },
          { t: 'trace', model: 'swin' },
        ],
      },

      // ======================================================== 5
      {
        id: 'costo',
        titleEn: 'Parameters and cost',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`Swin-T tiene ${qn('params.total')} parámetros (${qn('params.totalM')}) y hace ${qn('macs.totalG')} MACs por imagen a 224: casi lo mismo que una ResNet-50 (${qn('params.totalM', RN)}, ${qn('macs.totalG', RN)} MACs). El paper eligió las variantes así a propósito (§3.3): Swin-T con la complejidad de ResNet-50 (y de DeiT-S), Swin-S con la de ResNet-101, Swin-B con la de ViT-B/DeiT-B. Por stage: ${np('stage1')}, ${np('stage2')}, ${np('stage3')} y ${np('stage4')} parámetros; los merges, ${np('merge1')}, ${np('merge2')} y ${np('merge3')}; la cabeza, ${np('head')}.` },
          { t: 'params', model: 'swin', group: 'block' },
          { t: 'p', html: R`Fíjate en la asimetría. El stage 4, con solo 2 bloques, se lleva ${qn('node.stage4.paramsPct')} de los parámetros: trabaja a 8C y los parámetros van con C². El stage 3 (6 bloques a 4C) se lleva ${qn('node.stage3.paramsPct')} y casi la mitad de los MACs (${qn('node.stage3.macsPct')}). El stage 1 es al revés: ${qn('tokens')} tokens pero solo 96 canales, así que pesa ${qn('node.stage1.paramsPct')} en parámetros y ${qn('node.stage1.macsPct')} en MACs. Es el mismo patrón de una ResNet: los últimos stages concentran los pesos y los primeros, la resolución. Las tablas de relative position bias son una fracción mínima: ${qn('prim.rel_pos_bias.params')} parámetros en todo el modelo.` },
          { t: 'flops', model: 'swin' },
          { t: 'callout', kind: 'trap', title: 'Los "4.5G FLOPs" de Swin-T son MACs', html: R`<p>La Tabla 1(a) del paper lista Swin-T a 224² con 29M parámetros y "4.5G FLOPs". El calculador da ${qn('macs.totalG')} MACs: coincide, así que son <b>MACs</b>, igual que los "17.5G FLOPs" de DeiT-B en la misma tabla (<a href="#vit.costo">ViT</a>). En FLOPs reales, ${qn('flops.totalG')}FLOPs. Y los parámetros: el calculador cuenta ${qn('params.totalM')}; la Tabla 1(a) redondea a 29M, la Tabla 1 de ConvNeXt escribe 28M para el mismo modelo.</p>` },

          { t: 'h3', text: 'Lineal vs cuadrático: las ecuaciones 1 y 2 del paper' },
          { t: 'p', html: R`Para un mapa de N = h<sub>s</sub>·w<sub>s</sub> tokens con C canales, el paper (§3.2) compara la MSA global con la de ventanas, contando las multiplicaciones de matmul y sin el softmax:` },
          { t: 'math', display: true, tex: R`\begin{aligned}
\Omega(\mathrm{MSA}) &= 4NC^2 + 2N^2C &\qquad (1)\\
\Omega(\text{W-MSA}) &= 4NC^2 + 2M^2NC &\qquad (2)
\end{aligned}`, caption: 'Ecuaciones 1 y 2 de Liu et al. (2021), con N = hw. 4NC² = proyecciones Q, K, V (3NC²) y salida (NC²); 2N²C = QKᵀ + A·V. Con M fijo, (2) es lineal en N.' },
          { t: 'callout', kind: 'trap', title: 'En esas ecuaciones, h no son las cabezas', html: R`<p>El paper escribe 4hwC² + 2(hw)²C, con <b>h × w = alto × ancho del mapa de patches</b>. En el resto del Atlas, h son las cabezas. Si en una entrevista escribes la fórmula, di qué es cada letra. Notar también que las cabezas no aparecen: el costo de QKᵀ es h·N²·d<sub>h</sub> = N²C, independiente de cuántas cabezas haya.</p>` },
          { t: 'p', html: R`Con los números del stage 1 de Swin-T (N = ${qn('tokens')}, C = 96, M = 7), por bloque:` },
          { t: 'table', caption: 'Ecuaciones 1 y 2 evaluadas por el calculador (un bloque de cada stage, Swin-T @ 224)', head: ['Stage', 'Tokens N', 'Ventanas', 'QKᵀ + A·V en ventanas (2M²NC)', 'QKᵀ + A·V si fuera global (2N²C)', 'Global / ventanas'], rows: [
            ['1', qn('quantities.s1Tokens'), qn('quantities.s1Windows'), qn('metrics.s1ScoreMacs'), qn('metrics.s1GlobalScoreMacs'), '×' + qn('metrics.s1GlobalToWindow')],
            ['2', qn('quantities.s2Tokens'), qn('quantities.s2Windows'), qn('metrics.s2ScoreMacs'), qn('metrics.s2GlobalScoreMacs'), '×' + qn('metrics.s2GlobalToWindow')],
            ['3', qn('quantities.s3Tokens'), qn('quantities.s3Windows'), qn('metrics.s3ScoreMacs'), qn('metrics.s3GlobalScoreMacs'), '×' + qn('metrics.s3GlobalToWindow')],
            ['4', qn('quantities.s4Tokens'), qn('quantities.s4Windows'), qn('metrics.s4ScoreMacs'), qn('metrics.s4GlobalScoreMacs'), '×' + qn('metrics.s4GlobalToWindow')],
          ], note: 'La razón global/ventanas es N/M² = número de ventanas. En el stage 4 hay una sola ventana: ahí la atención en ventana <b>es</b> global.' },
          { t: 'p', html: R`<b>La lectura que se anota en una entrevista:</b> donde hay muchos tokens (stage 1) la atención global sería ×64 más cara en su parte cuadrática; donde hay pocos (stage 4) da lo mismo. Swin gasta la atención global justo donde es barata. Y como el término 2M²NC es lineal en N, <b>duplicar la resolución multiplica por ≈ 4 los MACs de todo el modelo</b>, igual que en una CNN, en lugar del ×16 de la parte cuadrática de ViT.` },

          { t: 'h3', text: 'Cómo escala' },
          { t: 'p', html: R`Mueve la resolución. Mira los tokens del stage 1, los MACs totales, la parte que va a QKᵀ y A·V (solo la parte que crece con N·M²) y la memoria del tensor de puntuaciones de un bloque.` },
          { t: 'scaling', model: 'swin', knobs: [{ key: 'res', values: [224, 448, 672, 896] }], show: ['tokens', 'params', 'macs', 'scoreMacsShare', 'attnMem'] },
          { t: 'p', html: R`<b>La ley de escala en palabras.</b> Duplicar la resolución (224 → 448) con M fijo multiplica los tokens de cada stage por 4 y las ventanas por 4; cada ventana sigue teniendo 49 tokens. Las lineales ≈ ×4, la parte de atención ≈ ×4 (no ×16) y la memoria del tensor de puntuaciones ≈ ×4. Los parámetros no cambian: la tabla de bias relativo depende de M, no de la resolución. Para cambiar M sí hay que tocar pesos: la tabla B̂ pasa de (2M−1)² a (2M'−1)² entradas y se interpola (bicúbica) al hacer fine-tuning a 384 con M = 12.` },

          { t: 'h3', text: 'Tamaños de la familia, frente a ViT y ResNet' },
          { t: 'compare', models: ['swin-t-224', 'swin-s-224', 'swin-b-224', 'swin-b-384', VB, RN], rows: ['params', 'macs', 'flops', 'tokens'] },
          { t: 'p', html: R`Configuraciones de la §3.3 del paper: Swin-T (C = 96, capas 2-2-6-2), Swin-S (C = 96, 2-2-18-2), Swin-B (C = 128, 2-2-18-2), con d<sub>h</sub> = 32 y α = 4 en todos; Swin-B @ 384 usa M = 12 (el nombre del checkpoint oficial es <code>swin_base_patch4_window12_384</code>). En "tokens", Swin cuenta los del stage 1 (stride 4) y ViT los de su única escala: no es una comparación de costo, es la resolución a la que trabaja cada uno. ResNet-50 no tiene tokens: el ${qn('tokens', RN)} de su columna son las posiciones de su mapa C5 (7×7), el último antes del pooling.` },
          { t: 'callout', kind: 'skip', html: R`<p><b>Sáltate esto:</b> los MACs de la máscara, del roll y de la partición. Son cero en el titular (no son matmuls), pero no son gratis en tiempo: son movimientos de memoria.</p>` },
        ],
      },

      // ======================================================== 6
      {
        id: 'entrenamiento',
        titleEn: 'Training',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`Swin se entrena como un clasificador supervisado y se transfiere como backbone. Dos regímenes en el paper (§4.1 y Apéndice A2): <b>solo ImageNet-1K</b> (1.28 M imágenes, 1,000 clases) con una receta tipo DeiT, o <b>preentrenamiento en ImageNet-22K</b> (14.2 M imágenes, ≈ 22K clases) y fine-tuning en ImageNet-1K. La pérdida es la entropía cruzada sobre los logits del pooling:` },
          { t: 'math', display: true, tex: R`\mathcal{L} = -\log \frac{\exp(\text{logit}_{y})}{\sum_{k=1}^{K}\exp(\text{logit}_k)}\qquad\text{(con label smoothing y, con Mixup/CutMix, etiquetas mezcladas)}`, caption: 'Entropía cruzada. Mixup y CutMix convierten la etiqueta en una mezcla de dos clases; la pérdida es la misma con un objetivo "suave".' },
          { t: 'kv', items: [
            ['Optimizador (ImageNet-1K)', 'AdamW, 300 épocas, cosine decay, 20 épocas de warmup lineal', '§4.1'],
            ['Batch, lr, weight decay', 'batch 1024, lr inicial 0.001, weight decay 0.05', '§4.1'],
            ['Augmentation y regularización', 'Casi todo lo de DeiT (RandAugment, Mixup, CutMix, random erasing, stochastic depth), sin repeated augmentation ni EMA porque "no mejoran"', '§4.1'],
            ['Stochastic depth', '0.2 / 0.3 / 0.5 para Swin-T / S / B', 'Apéndice A2.1'],
            ['Gradient clipping', 'norma máxima 1 según el paper; el <code>config.py</code> del repo oficial trae <code>TRAIN.CLIP_GRAD = 5.0</code> por defecto (el yaml de Swin-T no lo cambia)', 'Apéndice A2.1; repo microsoft/Swin-Transformer'],
            ['Preentrenamiento ImageNet-22K', 'AdamW, 90 épocas, decay lineal, 5 épocas de warmup, batch 4096, lr 0.001, wd 0.01', '§4.1'],
            ['Fine-tuning (de 22K a 1K, o de 224 a 384)', '30 épocas, batch 1024, lr constante 10⁻⁵, wd 10⁻⁸', '§4.1 y Apéndice A2'],
          ] },
          { t: 'callout', kind: 'note', html: R`<p>La combinación que el entrevistador espera oír: <b>AdamW + warmup + cosine + weight decay 0.05 + augmentation fuerte (RandAugment, Mixup, CutMix) + stochastic depth</b>. Es la receta de DeiT con pequeños cambios; desde Swin es la receta por defecto de casi cualquier backbone de visión, incluido ConvNeXt (que la usa para mostrar que buena parte de la mejora era receta). Stochastic depth sube con el tamaño del modelo: un modelo más profundo se regulariza más.</p>` },
          { t: 'h3', text: 'Resultados del paper (citados, no calculados)' },
          { t: 'table', caption: 'ImageNet-1K top-1 (Liu et al. 2021, Tabla 1)', head: ['Modelo', 'Resolución', 'Preentrenamiento', 'Top-1', 'Fuente'], rows: [
            ['DeiT-S', '224²', 'ImageNet-1K', '79.8 %', 'Tabla 1(a)'],
            ['Swin-T', '224²', 'ImageNet-1K', '81.3 %', 'Tabla 1(a)'],
            ['Swin-S', '224²', 'ImageNet-1K', '83.0 %', 'Tabla 1(a)'],
            ['DeiT-B', '224²', 'ImageNet-1K', '81.8 %', 'Tabla 1(a)'],
            ['Swin-B', '224²', 'ImageNet-1K', '83.5 %', 'Tabla 1(a)'],
            ['Swin-B', '384²', 'ImageNet-1K', '84.5 %', 'Tabla 1(a)'],
            ['Swin-B', '224²', 'ImageNet-22K', '85.2 %', 'Tabla 1(b)'],
            ['Swin-B', '384²', 'ImageNet-22K', '86.4 %', 'Tabla 1(b)'],
          ], note: 'Throughput de la misma tabla (V100, con el código de timm): Swin-T 755.2 img/s, DeiT-S 940.4 img/s. Swin-T tiene menos "FLOPs" que DeiT-S (4.5G vs 4.6G) y aun así es más lento: los MACs no son latencia.' },
          { t: 'h3', text: 'Ablaciones que vale la pena saber' },
          { t: 'table', caption: 'Liu et al. 2021, Tabla 4 (Swin-T; ImageNet-1K, COCO con Cascade Mask R-CNN, ADE20K con UperNet)', head: ['Variante', 'ImageNet top-1', 'COCO AP<sup>box</sup>', 'ADE20K mIoU'], rows: [
            ['Sin desplazamiento (todas las capas W-MSA)', '80.2', '47.7', '43.3'],
            ['Con shifted windows (Swin)', '81.3', '50.5', '46.1'],
            ['Sin posición', '80.1', '49.2', '43.8'],
            ['Posición absoluta (como ViT)', '80.5', '49.0', '43.2'],
            ['Absoluta + relativa', '81.3', '50.2', '44.0'],
            ['Relative position bias (Swin)', '81.3', '50.5', '46.1'],
          ] },
          { t: 'p', html: R`Dos lecturas: (1) el shift aporta poco en clasificación (+1.1) y mucho en tareas densas (+2.8 AP, +2.8 mIoU), porque ahí importa que la información cruce los bordes de ventana a alta resolución; (2) la posición absoluta casi no ayuda en clasificación y <b>empeora</b> la detección frente a no tener posición (49.0 vs 49.2). El paper lo atribuye a que un sesgo que favorece la invariancia a traslación sigue siendo preferible, sobre todo en tareas densas; además, una tabla absoluta aprendida a 224 hay que interpolarla para usarla a 1333 px. El bias relativo, en cambio, no depende del tamaño de la imagen.` },
          { t: 'h3', text: 'Transferencia a detección y segmentación' },
          { t: 'kv', items: [
            ['COCO (detección)', 'Entrenamiento multiescala (lado corto entre 480 y 800), AdamW lr 10⁻⁴, wd 0.05, batch 16, schedule 3x (36 épocas)', '§4.2'],
            ['ADE20K (segmentación)', 'UperNet, AdamW lr 6·10⁻⁵, wd 0.01, 160K iteraciones, 2 imágenes por GPU, entrada 512×512', '§4.3 y Apéndice A2'],
            ['Inicialización', 'Backbone preentrenado en ImageNet (1K o 22K); cuello y cabezas desde cero', '§4.2–4.3'],
          ] },
          { t: 'callout', kind: 'trap', title: '"A otra resolución hay que reentrenar"', html: R`<p>Falso, y a diferencia de ViT ni siquiera hay que interpolar nada si mantienes M: los pesos no dependen del número de tokens (no hay tabla de posiciones absoluta). Solo hace falta que el mapa de cada stage se pueda cortar en ventanas (o rellenar con padding, que es lo que hace el código de detección). Lo que sí obliga a tocar pesos es <b>cambiar M</b>: la tabla de bias relativo cambia de tamaño y se interpola. Ese fue uno de los problemas que motivó Swin V2 (<a href="#swin.variantes">variantes</a>).</p>` },
        ],
      },

      // ======================================================== 7
      {
        id: 'inferencia',
        titleEn: 'Inference',
        priority: 'core',
        blocks: [
          { t: 'steps', items: [
            { title: 'Preproceso', html: R`<p>Clasificación: resize + center crop a 224 (o 384), normalización de ImageNet. Detección: resize del lado corto (800 en COCO), sin crop; el tamaño resultante casi nunca es múltiplo de 32·M y el backbone rellena con padding.</p>` },
            { title: 'Patch embedding', html: R`<p>Una conv 4×4 s4 + LN: ${sh('x-img')} → ${sh('x-embed')}.</p>` },
            { title: 'Stages 1–4', html: R`<p>Cada bloque: LN → (roll) → partición → atención en 64, 16, 4, 1 ventanas → reverse → (roll inverso) → residual → LN → MLP → residual. Patch merging entre stages.</p>` },
            { title: 'Cabeza o features', html: R`<p>Clasificación: LN → promedio → lineal → ${sh('logits')}. Detección/segmentación: se toman ${sh('s1-out')}, ${sh('s2-out')}, ${sh('s3-out')}, ${sh('s4-out')} (cada uno con su LN) hacia el FPN o el decoder.</p>` },
          ] },
          { t: 'h3', text: 'Restricciones de resolución y ventana' },
          { t: 'p', html: R`Para que cada stage se pueda cortar en ventanas de M×M sin padding, el lado del mapa en <b>cada</b> stage tiene que ser múltiplo de M: H/4, H/8, H/16 y H/32. Basta con la última: <b>H múltiplo de 32·M</b>. Para M = 7, 32·7 = 224; para M = 12, 32·12 = 384. Por eso los checkpoints de clasificación vienen en pares exactos (224 con M = 7, 384 con M = 12) y no en 256 o 320.` },
          { t: 'callout', kind: 'senior', title: 'La regla del último stage: si el mapa cabe en una ventana, no hay shift', html: R`<p>En Swin-T @ 224 el stage 4 es de ${sh('s4-out')}: con M = 7 es <b>una sola ventana</b> que cubre todo el mapa. Desplazar la partición no conectaría nada nuevo (ya todos ven a todos) y solo agregaría máscara. La implementación oficial y timm aplican la regla "si el mapa no es más grande que la ventana, la ventana es el mapa y el shift es 0", así que el segundo bloque del stage 4 es, en la práctica, un W-MSA más; el calculador lo modela igual. Si alguien te pregunta "¿cuántos bloques con shift tiene Swin-T?", la respuesta no es "la mitad": es 1 + 1 + 3 = 5 de 12.</p>` },
          { t: 'h3', text: 'Qué domina la latencia y la memoria' },
          { t: 'p', html: R`<b>Pesos:</b> ${qn('params.total')} parámetros × 2 bytes (bf16) = ${qn('metrics.paramMem')}. <b>MACs:</b> ${qn('macs.totalG')}, de los cuales la atención propiamente dicha (QKᵀ y A·V) es solo ${qn('metrics.scoreMacsShare')}; si se cuentan también las proyecciones Q, K, V, O, el bloque de atención completo es ${qn('metrics.attnMacsShare')}. El resto son las lineales del MLP, el patch embedding, los merges y la cabeza. <b>Tensor de puntuaciones:</b> en un bloque del stage 1 son ${sh('s1-b1-scores')}, ${qn('metrics.attnMem')} por imagen en bf16, frente a ${qn('metrics.s1GlobalAttnMem')} si la atención del stage 1 fuera global.` },
          { t: 'p', html: R`¿Y entonces por qué Swin-T es más lento que DeiT-S en la Tabla 1 con menos MACs? Porque lo que no aparece en los MACs pesa: partición y reverse (permutes de 6 ejes que copian memoria), <code>roll</code>, la suma del bias relativo (un gather sobre la tabla) y de la máscara, y activaciones mucho más grandes en el stage 1 (${sh('s1-out')}, 16 veces los tokens de ViT). Son operaciones memory-bound; con batch grande en GPU se notan menos, y en runtimes de edge o con INT8 pueden dominar.` },
          { t: 'scaling', model: 'swin', knobs: [{ key: 'res', values: [224, 448, 896] }], show: ['tokens', 'macs', 'scoreMacsShare', 'attnMem'] },
          { t: 'h3', text: 'Trucos comunes' },
          { t: 'table', head: ['Truco', 'Qué hace', 'Cuándo importa'], rows: [
            ['Bias + máscara en un solo <code>attn_mask</code>', 'timm suma, en cada forward, el bias relativo y la máscara en un solo tensor aditivo y lo pasa como <code>attn_mask</code> a <code>F.scaled_dot_product_attention</code>: una sola llamada en lugar de matmul, suma, softmax y matmul por separado.', 'Siempre en GPU. Ojo: con una máscara densa arbitraria, SDPA no puede usar el kernel de FlashAttention y usa el memory-efficient (o el math).'],
            ['fp16 / bf16', 'Mitad de memoria; el −100 de la máscara cabe en fp16 sin problema.', 'Siempre en GPU.'],
            ['Padding a múltiplos de M', 'Rellena cada mapa de stage para cortarlo en ventanas y recorta después; es lo que hace el backbone de detección.', 'Entradas de tamaño arbitrario (detección).'],
            ['Exportar con cuidado', 'ONNX/TensorRT soportan <code>roll</code> y reshapes, pero validar numéricamente y medir: algunas versiones generan muchos kernels de copia.', 'Despliegue en edge.'],
            ['Cambiar de backbone', 'Si la latencia manda, ConvNeXt-T o una ResNet dan MACs parecidos con operaciones más simples.', 'Edge, INT8.'],
          ] },
          { t: 'callout', kind: 'estimate', html: R`<p>Latencias: no las inventes. La Tabla 1 del paper da throughput en V100 (Swin-T 755.2 img/s a 224, batch grande); para tu hardware, <span class="est">mide</span> con warmup, sincronización de CUDA, batch 1 y batch grande por separado, y en detección mide el pipeline completo (backbone + FPN + cabezas + NMS), donde el backbone suele ser una parte, no todo.</p>` },
        ],
      },

      // ======================================================== 8
      {
        id: 'fallas',
        titleEn: 'Failure modes and trade-offs',
        priority: 'core',
        blocks: [
          { t: 'list', ordered: true, items: [
            R`<b>Resolución y ventana acopladas.</b> La entrada tiene que ser compatible con 32·M o hay que rellenar; cambiar M obliga a interpolar las tablas de bias, y la calidad cae si se transfiere a ventanas mucho más grandes sin fine-tuning. Mitigación: padding (detección), fine-tuning tras interpolar, o Swin V2 (bias continuo en coordenadas logarítmicas).`,
            R`<b>Contexto global tardío.</b> En los primeros stages cada token solo ve su ventana y las vecinas; el alcance global solo llega en el stage 4. Para tareas que necesitan relaciones de larga distancia a alta resolución desde temprano, es una limitación. Mitigación: más profundidad, o arquitecturas con algunos bloques globales (ViTDet usa ventanas + unos pocos bloques globales).`,
            R`<b>Latencia mayor que lo que dicen sus MACs.</b> Particiones, rolls, máscaras y gathers son operaciones de memoria; en edge o con cuantización pueden dominar. Mitigación: medir, fusionar bias + máscara, o elegir ConvNeXt.`,
            R`<b>Incómodo para preentrenamiento enmascarado y para VLMs.</b> Las ventanas necesitan la cuadrícula completa: no se puede descartar 75 % de los tokens como en MAE, y la salida es una pirámide, no una secuencia plana para un LLM. Mitigación: SimMIM (enmascarar con un token en lugar de quitar), Hiera (jerárquico pero sin ventanas desplazadas, diseñado para MAE).`,
          ] },
          { t: 'table', caption: 'Swin-T vs ViT-B/16 vs ConvNeXt-T vs ResNet-50 (filas = criterios)', head: ['Criterio', 'Swin-T', 'ViT-B/16', 'ConvNeXt-T', 'ResNet-50'], rows: [
            ['Parámetros / MACs a 224', R`${qn('params.totalM')} / ${qn('macs.totalG')} (calculador)`, R`${qn('params.totalM', VB)} / ${qn('macs.totalG', VB)} (calculador)`, '29M / 4.5G (ConvNeXt, Tabla 1, "FLOPs" = MACs)', R`${qn('params.totalM', RN)} / ${qn('macs.totalG', RN)} (calculador)`],
            ['ImageNet-1K top-1 a 224 (solo 1K)', '81.3 % (Swin, Tabla 1(a))', '—: con solo 1K y la receta original, ViT-B/16 queda bajo; DeiT-B llega a 81.8 % (Swin, Tabla 1(a))', '82.1 % (ConvNeXt, Tabla 1)', 'Depende mucho de la receta; no lo comparo'],
            ['Pirámide de features', 'Sí (strides 4–32)', 'No (stride 16)', 'Sí (strides 4–32)', 'Sí (strides 4–32)'],
            ['Mezcla espacial', 'Atención en ventana 7×7 + shift', 'Atención global', 'Conv depthwise 7×7', 'Conv 3×3'],
            ['Costo vs número de píxeles (H·W)', 'Lineal (M fijo)', 'Cuadrático en tokens', 'Lineal', 'Lineal'],
            ['Posición', 'Bias relativo en ventana', 'Absoluta aprendida (interpolar)', 'Implícita', 'Implícita'],
            ['Detección / segmentación', 'Backbone fuerte, drop-in en FPN', 'Necesita adaptación (ViTDet)', 'Drop-in, al nivel de Swin', 'Backbone clásico'],
            ['Preentrenamiento enmascarado (MAE)', 'Incómodo (SimMIM)', 'Natural', 'Posible con convs dispersas (ConvNeXt V2)', 'Raro'],
            ['Encoder de VLM', 'Raro', 'Estándar', 'A veces (CLIP-ConvNeXt de OpenCLIP)', 'Raro hoy'],
            ['Despliegue en edge', 'Más delicado (roll, máscaras)', 'Bueno con TensorRT', 'Simple (solo convs, LN)', 'Muy maduro'],
          ], note: 'Los números de ConvNeXt-T y los accuracies son de las tablas citadas; parámetros y MACs de Swin-T, ViT-B/16 y ResNet-50 salen del calculador del Atlas.' },
          { t: 'callout', kind: 'senior', title: 'ConvNeXt, "la respuesta de las CNN"', html: R`<p>${CONVNEXT} tomó una ResNet-50 y le aplicó, una a una, las decisiones de diseño de Swin: stem "patchify" 4×4 stride 4, proporciones de stages 1:1:3:1 (como 2-2-6-2), convolución depthwise de <b>7×7</b> (el paper la justifica por el tamaño de ventana de Swin), bottleneck invertido (×4, como el MLP), LayerNorm en lugar de BatchNorm, GELU, menos normalizaciones y activaciones, y capas de downsampling separadas (como el patch merging), todo con la receta de entrenamiento de Swin/DeiT. ConvNeXt-T llega a 82.1 % contra 81.3 % de Swin-T con "FLOPs" parecidos (Tabla 1). Lectura: buena parte de la ventaja de Swin era la <b>macro-arquitectura y la receta</b>, no la atención en sí. Lo que un entrevistador quiere oír: "attention inside a 7-by-7 window and a 7-by-7 depthwise conv are close cousins; the difference is that attention weights are input-dependent."</p>` },
          { t: 'callout', kind: 'interview', html: R`<p>"For a detection or segmentation backbone at high resolution I'd pick a hierarchical model, Swin or ConvNeXt, because they give a stride-4-to-32 pyramid at a cost linear in the number of pixels. Between them I'd decide by checkpoint availability and deployment: ConvNeXt is simpler to export and quantize. For a multimodal encoder I'd use a plain ViT, because the ecosystem of contrastive checkpoints and the flat token sequence fit an LLM."</p>` },
        ],
      },

      // ======================================================== 9
      {
        id: 'variantes',
        titleEn: 'Variants and descendants',
        priority: 'extra',
        blocks: [
          { t: 'table', head: ['Modelo', 'Qué cambia (una línea)', 'Dónde lo ves'], rows: [
            [R`Swin V2 (${V2})`, 'Para escalar a 3 mil millones de parámetros y 1,536×1,536 px: <b>res-post-norm</b> (la LN va a la salida de cada rama residual, porque con pre-LN la amplitud de las activaciones se acumula capa a capa), <b>scaled cosine attention</b> (cos(q, k)/τ + B, con τ aprendido por cabeza y capa, mayor que 0.01) y <b>log-spaced continuous position bias</b> (una red chica genera el bias a partir de coordenadas relativas en escala log, así se transfiere a ventanas más grandes). Preentrena con SimMIM.', '—'],
            ['Video Swin (Liu et al., CVPR 2022, arXiv:2106.13230)', 'Ventanas 3D desplazadas (tiempo × alto × ancho) para clasificación de video.', '—'],
            ['Swin-UNETR (Hatamizadeh et al., 2022, arXiv:2201.01266)', 'Encoder Swin 3D con decoder tipo U-Net para segmentación de imágenes médicas volumétricas.', '—'],
            ['PVT (Wang et al., ICCV 2021, arXiv:2102.12122)', 'Otra forma de pirámide: atención global pero con K y V reducidas espacialmente ("spatial-reduction attention").', '—'],
            ['MViT / MViTv2 (Fan et al., ICCV 2021, arXiv:2104.11227; Li et al., CVPR 2022, arXiv:2112.01526)', 'Pirámide con "pooling attention": se reduce la resolución de Q, K y V con pooling dentro de la atención.', '—'],
            ['Hiera (Ryali et al., ICML 2023, arXiv:2306.00989)', 'Jerárquico "sin adornos": quita bias relativo, shifts y convoluciones; la localidad la aprende con preentrenamiento MAE. Es el image encoder de SAM 2.', '<a href="#sam2">SAM 2</a>'],
            ['ViTDet (Li et al., ECCV 2022, arXiv:2203.16527)', 'La respuesta contraria: ViT plano + atención en ventanas con pocos bloques globales + pirámide simple al final.', '<a href="#vit.variantes">ViT</a>'],
            [R`ConvNeXt (${CONVNEXT})`, 'La respuesta de las CNN: ResNet modernizada con las decisiones de diseño de Swin; iguala o supera a costo comparable.', '<a href="#swin.fallas">Fallas</a>'],
            ['Grounding DINO (Liu et al., ECCV 2024, arXiv:2303.05499)', 'Detector de vocabulario abierto con backbone Swin-T (o Swin-L) y fusión con texto.', '<a href="#grounding-dino">Grounding DINO</a>'],
            ['Mask2Former (Cheng et al., CVPR 2022, arXiv:2112.01527)', 'Segmentación universal tipo DETR; sus mejores resultados usan Swin-L como backbone.', '<a href="#detr">DETR</a> (familia)'],
          ] },
          { t: 'callout', kind: 'connect', html: R`<p>Patrón para el resto del Atlas: cuando un detector o segmentador dice "backbone Swin-T", lo que entrega son los cuatro mapas de esta página a strides 4–32. Lo vas a ver en <a href="#grounding-dino">Grounding DINO</a> y, como contraste jerárquico con ventanas <b>sin</b> desplazar (más unos pocos bloques globales), en <a href="#sam2">SAM 2</a> con Hiera.</p>` },
        ],
      },

      // ======================================================== 10
      {
        id: 'entrevista',
        titleEn: 'Interview questions',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`Esto es lo que te van a preguntar sobre Swin. Las preguntas van en inglés, las respuestas en español para entender el mecanismo, y varias tienen la frase senior en inglés para decirla tal cual.` },
          { t: 'followups', items: [
            { q: 'Walk me through the shapes of Swin-T at 224, stage by stage.',
              junior: 'La imagen se divide en ventanas y pasa por cuatro stages.',
              senior: R`${sh('x-img')} → conv 4×4 s4 + LN → ${sh('x-embed')} (stride 4) → stage 1, 2 bloques, ${sh('s1-out')} → patch merging → ${sh('s2-out')} → stage 2 → merge → ${sh('s3-out')} → stage 3 (6 bloques) → merge → ${sh('s4-out')} → stage 4 → LN → promedio → ${sh('pooled')} → ${sh('logits')}. Dentro de un bloque del stage 1: ventanas ${sh('s1-b1-win')}, por cabeza ${sh('s1-b1-q')}, puntuaciones ${sh('s1-b1-scores')}.`,
              why: 'La pregunta de nivel 2: strides 4–32, canales ×2 por stage, y la forma de ventana nW×M²×C.',
              say: 'Stride-4 tokens, four stages at 56, 28, 14 and 7 with 96, 192, 384 and 768 channels, 2-2-6-2 blocks, and inside each block 7-by-7 windows of 49 tokens.' },
            { q: 'Why is window attention linear in the number of tokens? Give numbers.',
              junior: 'Porque las ventanas son más chicas.',
              senior: R`Cada token se compara con M² tokens de su ventana, no con N: QKᵀ + A·V cuestan 2M²NC en lugar de 2N²C (ec. 1–2). Con M fijo es lineal en N. En el stage 1 de Swin-T: ${qn('metrics.s1ScoreMacs')} MACs por bloque en ventanas contra ${qn('metrics.s1GlobalScoreMacs')} si fuera global, ×${qn('metrics.s1GlobalToWindow')} (= N/M², las ventanas). Las proyecciones (4NC²) no cambian. Duplicar la resolución multiplica todo ≈ ×4, como en una CNN: "lineal" es lineal en H·W (los tokens), o sea cuadrático en el lado. <b>El precio</b>: el alcance de cada bloque queda fijo en 7×7 tokens. Si duplicas la resolución, cada ventana cubre ¼ del área de imagen que cubría, y el contexto global solo llega en los últimos stages, a través de los shifts y los merges. Y la linealidad vale para M fijo: si agrandas M para recuperar contexto, el término 2M²NC crece con M². Por eso ViTDet intercala unos pocos bloques de atención global entre los de ventana, y Swin V2 sube M al subir la resolución.`,
              why: 'Dar la fórmula, saber que las proyecciones no cambian y poner el número del stage 1 es lo que se anota. La repregunta es "¿y qué pierdes?": el alcance fijo por bloque.',
              say: 'Each query attends to M-squared keys instead of N, so the quadratic term becomes 2 M-squared N C, linear in the number of tokens for a fixed window, which is still quadratic in the image side. The price is a fixed 7-by-7 reach per block, which is why ViTDet interleaves a few global blocks.' },
            { q: 'What problem do shifted windows solve, and what happens without them?',
              junior: 'Hacen que las ventanas se solapen.',
              senior: 'Con una partición fija, las ventanas son islas: ningún token ve más allá de su ventana en todo el stage. Al desplazar la partición ⌊M/2⌋ en bloques alternos, cada ventana nueva cubre partes de cuatro ventanas viejas y la información cruza los bordes; con varios bloques, el campo receptivo crece como al apilar convs. Las ventanas nunca se solapan dentro de un bloque. Sin shift (Tabla 4): 80.2 vs 81.3 top-1, 47.7 vs 50.5 AP<sup>box</sup> en COCO, 43.3 vs 46.1 mIoU en ADE20K: el efecto es mucho mayor en tareas densas.',
              why: 'La trampa es decir que se solapan. La señal senior es el ablation y que el impacto es mayor en detección.', trap: true },
            { q: 'How is the shifted-window attention computed efficiently? Why is a mask needed?',
              junior: 'Se hace padding en los bordes.',
              senior: R`Con <b>cyclic shift</b>: <code>torch.roll</code> del mapa −⌊M/2⌋ en ambos ejes, partición regular en ventanas y la misma atención batched; después roll inverso. Así siguen siendo 64 ventanas de 49 tokens en el stage 1, contra 81 ventanas de tamaños distintos (o con padding) si se desplazara la partición sin enrollar. El enrollado pega en una misma ventana tokens que no son vecinos en la imagen (el borde inferior con el superior), así que se suma una máscara de −100 entre tokens de regiones distintas (9 regiones) antes del softmax. La máscara depende solo de la geometría: es un buffer precalculado.`,
              why: 'Cyclic shift + máscara + "mismo número de ventanas" es la respuesta completa. Padding es la alternativa más lenta (Tabla 5).', trap: true },
            { q: 'Why shifted non-overlapping windows instead of a sliding window around each token, like a convolution?',
              junior: 'Porque la ventana deslizante es más cara en FLOPs.',
              senior: R`No es por los FLOPs: una ventana deslizante de 7×7 cuesta lo mismo en multiplicaciones (cada consulta contra 49 claves). Es por el <b>acceso a memoria</b>. Con una ventana deslizante cada consulta tiene su propio conjunto de claves: hay que hacer un gather distinto por token (o un <code>unfold</code> que copia cada clave 49 veces) y no queda una matmul densa. Con ventanas que no se solapan, las 49 consultas de una ventana comparten exactamente las mismas 49 claves, así que la atención es una matmul batched estándar de (B·n<sub>W</sub>) × 49 × 49, el mismo kernel que ViT. Tabla 5 del paper, Swin-T en V100: sliding window ingenuo 183 FPS, sliding window con kernel CUDA propio 488, shifted windows 755. El precio es que la vecindad de un token depende de dónde caen los bordes de su ventana; el shift alternado lo compensa bloque a bloque. Contraste moderno: Neighborhood Attention (NAT, Hassani et al., CVPR 2023, arXiv:2204.07143) volvió a la ventana deslizante con kernels dedicados.`,
              why: 'Trampa: decir que la ventana deslizante tiene más FLOPs. La respuesta senior es acceso a memoria y matmuls densas, con el número de la Tabla 5.', trap: true,
              say: 'It is not about FLOPs but memory access. In a sliding window every query has its own key set, so you need per-token gathers. With non-overlapping windows all 49 queries in a window share the same 49 keys, so attention is one dense batched matmul, the same kernel as ViT. The paper measures 755 versus 488 frames per second against a custom sliding-window kernel.' },
            { q: 'What is the relative position bias, and how many parameters does it have?',
              junior: 'Es un embedding de posición que se suma a los tokens, como en ViT.',
              senior: R`No se suma a los tokens: se suma a las puntuaciones, dentro del softmax: SoftMax(QKᵀ/√d + B)V. B<sub>ij</sub> depende solo del desplazamiento (Δy, Δx) entre los tokens i y j de la ventana, que va de −(M−1) a M−1 en cada eje: (2M−1)² = 169 valores por cabeza, tomados de una tabla aprendida B̂. En el stage 1 de Swin-T son 169 × 3 cabezas por bloque; en todo Swin-T, ${qn('prim.rel_pos_bias.params')} parámetros. El índice que expande B̂ a 49×49 es un buffer. Es invariante a traslación dentro de la ventana y no depende del tamaño de la imagen; por eso supera a la posición absoluta, sobre todo en detección (50.5 vs 49.0 AP<sup>box</sup>, Tabla 4).`,
              why: 'Trampa: confundirlo con una position embedding sumada a la entrada. Contar 169 por cabeza y distinguir parámetro de buffer es lo que se anota.', trap: true },
            { q: 'How does patch merging compare to a strided convolution in a ResNet?',
              junior: 'Es un max-pooling.',
              senior: R`Es un downsampling aprendido de factor 2: concatena los vectores de cada bloque de 2×2 tokens (C → 4C, tokens ÷4), LN sobre los 4C y una lineal 4C → 2C sin bias. Equivale a una conv 2×2 con stride 2 de C a 2C (con una LN en medio). Igual que en una ResNet, ÷2 la resolución y ×2 los canales para que cada stage cueste parecido. Para el primer merge de Swin-T: ${sh('s1-out')} → ${sh('m1-concat')} → ${sh('m1-out')}, ${np('merge1')} parámetros.`,
              why: 'Conectar con lo que ya sabes (stride 2, doble de canales) y saber el detalle 4C → 2C sin bias.' },
            { q: 'You are replacing the ResNet-50 in a Mask R-CNN with Swin-T. What changes?',
              junior: 'Nada, se cambia el backbone y ya.',
              senior: 'Casi nada en el cuello: el FPN recibe cuatro mapas a strides 4, 8, 16, 32 como antes, solo con otros canales (96, 192, 384, 768 en vez de 256, 512, 1024, 2048), así que cambian las convs laterales 1×1 del FPN. En el backbone: agregar una LN a cada salida, reacomodar tokens a mapa C×H×W, y rellenar cada stage a múltiplos de M porque las imágenes de COCO no son múltiplos de 224. En el entrenamiento: AdamW (lr 10⁻⁴, wd 0.05) en lugar de SGD, que es lo que usa el paper (§4.2). Resultado del paper con Cascade Mask R-CNN: 46.3 → 50.5 AP<sup>box</sup> a costo parecido (Tabla 2(a)).',
              why: 'Es la pregunta práctica. Los canales del FPN, el padding y el cambio de optimizador muestran que lo hiciste o lo pensaste en serio.' },
            { q: 'Can you run a Swin checkpoint trained at 224 on 512×512 images? What about 300×300?',
              junior: 'No, la resolución está fija.',
              senior: 'A 512: los pesos sirven (no hay posiciones absolutas), pero 512/32 = 16 no es múltiplo de 7, así que hay que rellenar cada mapa a múltiplos de M o cambiar M. A 448 (= 2·224) entra sin padding: 112, 56, 28, 14 son múltiplos de 7. A 300 es peor: 300/4 = 75 tokens por lado, que no es múltiplo de 7 ni par, así que además hay que rellenar antes de cada patch merging (agrupa 2×2). Si cambias M (por ejemplo a 12 para 384), la tabla de bias relativo cambia de 13² a 23² por cabeza y se interpola, mejor con fine-tuning. La regla general: H múltiplo de 32·M para no rellenar.',
              why: 'Trampa: creer que, como ViT, necesita interpolar posiciones; o no saber de la restricción de divisibilidad.', trap: true },
            { q: 'How many blocks in Swin-T actually use a shifted window?',
              junior: 'La mitad: 6 de 12.',
              senior: 'Cinco. Los bloques pares de cada stage son SW-MSA (1 + 1 + 3 + 1 = 6 en papel), pero en el stage 4 el mapa es de 7×7 con M = 7: una sola ventana. La implementación oficial y timm ponen shift = 0 cuando el mapa no es más grande que la ventana, porque desplazar no conectaría nada nuevo. Así que el segundo bloque del stage 4 es otro W-MSA, que además es atención global sobre los 49 tokens.',
              why: 'Detalle de implementación que separa a quien leyó el código. Lo mismo pasa con Swin-B @ 384 (stage 4 de 12×12 con M = 12).', trap: true },
            { q: 'Swin-T has fewer FLOPs than DeiT-S but lower throughput. Why?',
              junior: 'Porque la atención es más cara.',
              senior: 'Porque los "FLOPs" (en realidad MACs) cuentan solo matmuls. Swin agrega muchas operaciones memory-bound: particiones y reverse (permutes que copian), rolls, el gather del bias relativo, la máscara, y activaciones grandes en el stage 1 (16 veces los tokens de DeiT-S). Además, las secuencias de 49 tokens dan matmuls chicas, menos eficientes en GPU. En la Tabla 1: Swin-T 4.5G y 755.2 img/s, DeiT-S 4.6G y 940.4 img/s (V100). MACs no son latencia.',
              why: 'La respuesta senior separa conteo de operaciones y tiempo, y nombra qué es memory-bound.', trap: true },
            { q: 'Swin or ConvNeXt as a detection backbone?',
              junior: 'Swin, porque los transformers son mejores.',
              senior: 'A igual tamaño y receta rinden parecido: ConvNeXt replicó las decisiones de diseño de Swin con convs (depthwise 7×7, stem 4×4 s4, stages 1:1:3:1, LN, GELU) y la iguala o supera (Tabla 1 de ConvNeXt: 82.1 vs 81.3 top-1 en la variante T), y como backbone de detección empatan: con Cascade Mask R-CNN 3× en COCO, ConvNeXt-T y Swin-T dan 50.4 AP<sup>box</sup> y 43.7 AP<sup>mask</sup> cada uno (Tabla 3 de ConvNeXt; el paper de Swin reporta 50.5 para Swin-T). Elijo por: checkpoints disponibles para mi dominio, facilidad de despliegue (ConvNeXt es solo convs y LN, más fácil de exportar y cuantizar) y lo que use el detector de referencia que voy a adaptar (por ejemplo, Grounding DINO viene con Swin). La atención en ventana tiene pesos dependientes del contenido; en la práctica eso no se tradujo en una ventaja clara.',
              why: 'Nombrar ConvNeXt y decidir por criterios de ingeniería, no por "transformer > CNN".', trap: true },
            { q: 'If Swin is so good for dense tasks, why do CLIP, SAM and most VLMs use a plain ViT?',
              junior: 'Porque Swin es más nuevo y todavía no se adoptó.',
              senior: 'Tres razones. (1) Escala y ecosistema: los mayores preentrenamientos (CLIP, SigLIP, MAE, DINOv2) se hicieron con ViT plano, que es más simple de escalar y paralelizar. (2) MAE: el ViT plano puede descartar 75 % de los tokens y procesar solo los visibles; las ventanas necesitan la cuadrícula completa. (3) Interfaz: un VLM quiere una secuencia plana de tokens para el LLM, no una pirámide. Y ViTDet mostró que un ViT plano con ventanas y una pirámide simple al final también sirve para detección. SAM 2 volvió a lo jerárquico, pero con Hiera, diseñado para MAE.',
              why: 'Muestra que sabes por qué ganó ViT en multimodal, no solo qué es Swin.' },
            { q: 'Where is the inductive bias in Swin compared to ViT and a CNN?',
              junior: 'Swin no tiene sesgo inductivo, es un transformer.',
              senior: 'Swin recupera parte del sesgo de una CNN: localidad (ventanas de 7×7), jerarquía (stages con downsampling) y una posición relativa invariante a traslación dentro de la ventana. No es equivariante a traslación como una conv: la partición está fija a la cuadrícula y desplazar la imagen un par de tokens cambia qué tokens comparten ventana. Por eso le saca más a ImageNet-1K que un ViT plano con la misma receta: Swin-T 81.3 vs DeiT-S 79.8 % a costo parecido (Tabla 1(a)). Ojo, DeiT también entrena solo en ImageNet-1K (sin JFT): la diferencia es el sesgo de la arquitectura, no los datos.',
              why: 'Ubicarlo entre ViT y CNN con precisión, no afirmar equivariancia a traslación, y no decir que ViT "necesita JFT": DeiT ya lo resolvió con receta.', trap: true },
            { q: 'It is today, not 2021. For each case, would you pick Swin, a plain ViT, or a CNN: (a) real-time detection on a Jetson, (b) instance segmentation on 1024-px industrial images with a few thousand labels, (c) the vision encoder of a VLM or a robot policy?',
              junior: 'Swin para todo, porque es el más nuevo de los tres.',
              senior: R`(a) <b>CNN</b> (un detector de la familia YOLO, o un ConvNeXt chico como backbone): convs y BatchNorm que se fusionan, INT8 maduro en TensorRT y latencia predecible. Swin paga <code>roll</code>, partición y máscaras, que son memory-bound justo donde el edge sufre; mídelo antes de descartarlo, pero arranco por la CNN. (b) Dos opciones razonables, y decido por checkpoint y latencia: un backbone <b>jerárquico</b> (Swin o ConvNeXt) con Mask R-CNN o Mask2Former, que da la pirámide sin adaptación, tiene checkpoints de detección listos y a 1024 px escala lineal en píxeles; o un <b>ViT plano con un preentrenamiento fuerte</b> (DINOv2, o MAE) con ViTDet o ViT-Adapter, que con pocas etiquetas puede transferir mejor, porque un buen preentrenamiento a escala vale más que el sesgo de la arquitectura. A 1024 px el ViT plano necesita atención en ventanas en la mayoría de los bloques (eso hace ViTDet). Con pocos miles de etiquetas, lo que más pesa es el preentrenamiento y la augmentation, no Swin vs ConvNeXt. (c) <b>ViT plano</b> (SigLIP, CLIP, DINOv2): ahí están los checkpoints alineados con lenguaje, y la salida es una secuencia plana de tokens para el LLM o la política (OpenVLA, Kim et al., 2024, arXiv:2406.09246, junta features de DINOv2 y SigLIP). Regla general: el checkpoint, el runtime y los datos deciden más que la arquitectura.`,
              why: 'Muestra criterio de ingeniería: decidir por checkpoint, runtime y datos, no por "transformer > CNN". Nombrar ViTDet para el caso (b) y SigLIP/DINOv2 para el (c) es la señal.',
              say: 'Edge real time: a CNN, because it fuses and quantizes cleanly. Dense prediction at high resolution: a hierarchical backbone like Swin or ConvNeXt if detection checkpoints exist, or a strong self-supervised plain ViT with ViTDet if labels are scarce. VLMs and robot policies: a plain ViT like SigLIP or DINOv2, because that is where the aligned checkpoints are and it outputs a flat token sequence.' },
            { q: 'What did Swin V2 change to scale to billions of parameters and high resolution?',
              junior: 'Más capas y más datos.',
              senior: R`Tres cambios (${V2}): (1) <b>res-post-norm</b>: la LN pasa a la salida de cada rama residual, porque con pre-LN la amplitud de las activaciones crece capa a capa y entrenar modelos enormes se vuelve inestable; (2) <b>scaled cosine attention</b>: cos(q, k)/τ + B en vez de qk/√d, con τ aprendido, para que unas pocas parejas no dominen la atención; (3) <b>log-spaced continuous position bias</b>: una red chica genera el bias desde coordenadas relativas en escala log, para transferir de ventanas chicas a grandes sin interpolar una tabla. Más SimMIM para preentrenar con menos etiquetas.`,
              why: 'Bonus senior: saber que los tres cambios atacan estabilidad y transferencia de resolución/ventana.' },
          ] },
          { t: 'callout', kind: 'interview', title: 'Dilo así (en inglés)', html: R`<p><b>Shifted windows:</b> "Windows never overlap within a block. In every other block the partition is shifted by half a window, implemented as a cyclic roll plus an attention mask, so the number of windows stays the same and information crosses window borders."</p><p><b>Relative position bias:</b> "It's a learned scalar per head for each relative offset inside the window, 13-by-13 offsets for a 7-by-7 window, added to the attention logits before the softmax. It's translation invariant and independent of image size."</p><p><b>Backbone:</b> "Patch merging halves the resolution and doubles the channels, so Swin outputs the same C2 to C5 pyramid as a ResNet and drops into an FPN."</p>` },
          { t: 'qa', items: [
            { q: '¿Cuántas ventanas y de qué forma tiene el stage 1 de Swin-T @ 224?', a: R`${qn('quantities.s1Windows')} ventanas de 7×7 = 49 tokens: el tensor de ventanas es ${sh('s1-b1-win')} y, por cabeza, ${sh('s1-b1-q')}.` },
            { q: '¿Cuánto pesa el tensor de puntuaciones de un bloque del stage 1, y cuánto pesaría con atención global?', a: R`${qn('metrics.attnMem')} en bf16 por imagen (${sh('s1-b1-scores')}) contra ${qn('metrics.s1GlobalAttnMem')} con atención global (3 cabezas × ${qn('tokens')}²).` },
            { q: '¿Por qué la resolución de clasificación es 224 con M = 7 y 384 con M = 12?', a: 'Porque el mapa del stage 4 es H/32 y tiene que ser múltiplo de M: 224 = 32·7 y 384 = 32·12.' },
          ] },
        ],
      },

      // ======================================================== 11
      {
        id: 'practica',
        titleEn: 'Active practice',
        priority: 'core',
        blocks: [
          { t: 'p', html: R`Primero el diagrama sin mirar; después las formas con números; al final, los "¿qué pasa si…?". Todas las respuestas las calcula el calculador.` },
          { t: 'h3', text: 'Diagrama en blanco: el modelo completo' },
          { t: 'blankdiagram', diagram: 'swin-overview', slots: [
            { node: 'patch-embed', ask: 'label' },
            { node: 'merge1', ask: 'label' },
            { node: 'stage1', tensor: 's1-out', ask: 'shape' },
            { node: 'merge3', tensor: 'm3-out', ask: 'shape' },
            { node: 'pool', ask: 'label' },
          ] },
          { t: 'h3', text: 'Diagrama en blanco: atención con ventanas desplazadas' },
          { t: 'blankdiagram', diagram: 'swin-swmsa', slots: [
            { node: 'shift', ask: 'label' },
            { node: 'partition', tensor: 's1-b2-win', ask: 'shape' },
            { node: 'bias', ask: 'label' },
            { node: 'mask', ask: 'label' },
            { node: 'unshift', ask: 'label' },
          ] },
          { t: 'h3', text: '¿Qué forma tiene este tensor?' },
          { t: 'shapedrill', model: 'swin', pool: 'all', configs: ['swin-t-224', 'swin-b-224', 'swin-b-384'] },
          { t: 'h3', text: '¿Qué pasa si…?' },
          { t: 'whatif', items: [
            { q: 'Duplicas la resolución de Swin-T: 224 → 448 (M = 7). ¿Por qué factor cambia el número de tokens del stage 1?', change: { res: 448 }, ask: 'tokens' },
            { q: 'Misma duplicación (224 → 448). ¿Por qué factor cambia la memoria del tensor de puntuaciones de un bloque del stage 1? (Compáralo con el ×16 de ViT.)', change: { res: 448 }, ask: 'attnMem' },
            { q: 'Misma duplicación. ¿Por qué factor cambian los MACs totales?', change: { res: 448 }, ask: 'macs' },
            { q: 'Misma duplicación. ¿Y los parámetros?', change: { res: 448 }, ask: 'params' },
            { q: 'Pasas a 896 px (×4 de lado). ¿Por qué factor cambian los MACs totales?', change: { res: 896 }, ask: 'macs' },
          ] },
          { t: 'h3', text: 'Estima y depura' },
          { t: 'qa', items: [
            { q: 'Tu Swin-T entrenado a 224 falla con un error de forma al pasarle imágenes de 256×256. ¿Qué pasa y cómo lo arreglas?', a: '256/4 = 64 tokens por lado en el stage 1, y 64 no es múltiplo de 7: la partición en ventanas (un view a (h/M, M, w/M, M)) no cierra. Opciones: redimensionar a 224 o 448, rellenar cada mapa a múltiplos de M dentro del bloque (como el backbone de detección), o usar una implementación que lo haga (timm con tamaño dinámico).' },
            { q: 'Implementas SW-MSA y te olvidas de la máscara. ¿Falla el código? ¿Qué notas?', a: 'No falla: las formas son las mismas. Notarás una caída de calidad, sobre todo en los bordes de la imagen, porque las ventanas del borde mezclan tokens de lados opuestos de la imagen. Es un bug silencioso típico; se detecta comparando contra la implementación de referencia con los mismos pesos.' },
            { q: 'Implementas SW-MSA y te olvidas del roll inverso. ¿Qué pasa?', a: 'Tampoco falla. El residual suma a cada token la salida de otro token desplazado 3 posiciones en cada eje: el modelo se entrena con features corridas y, con un checkpoint preentrenado, el accuracy se desploma.' },
          ] },
          { t: 'h3', text: 'Escríbelo: partición en ventanas, reverse y máscara del shift' },
          { t: 'p', html: R`El ejercicio de código que piden cuando sale Swin. Sin mirar: dado <code>x: (B, H, W, C)</code> con H y W múltiplos de M, devuelve las ventanas <code>(B·n_W, M², C)</code> y su inverso. Después, la máscara del bloque desplazado y el esqueleto de SW-MSA (roll, partición, atención, reverse, roll inverso). Anota la forma en cada línea. La solución está verificada en PyTorch contra timm (<code>window_partition</code>, <code>window_reverse</code> y el <code>attn_mask</code> de <code>SwinTransformerBlock</code>, iguales elemento a elemento).` },
          { t: 'code', title: 'Solución de referencia (PyTorch)', files: [
            { name: 'window_ops.py', lang: 'python', code: [
              'import torch',
              '',
              '',
              'def window_partition(x, M):                       # x: (B, H, W, C), H y W múltiplos de M',
              '    B, H, W, C = x.shape',
              '    x = x.view(B, H // M, M, W // M, M, C)         # (B, H/M, M, W/M, M, C)',
              '    x = x.permute(0, 1, 3, 2, 4, 5).contiguous()   # (B, H/M, W/M, M, M, C): ejes de ventana juntos',
              '    return x.view(-1, M * M, C)                    # (B·nW, M², C)',
              '',
              '',
              'def window_reverse(w, M, H, W):                   # w: (B·nW, M², C)',
              '    C = w.shape[-1]',
              '    x = w.view(-1, H // M, W // M, M, M, C)        # (B, H/M, W/M, M, M, C)',
              '    x = x.permute(0, 1, 3, 2, 4, 5).contiguous()   # (B, H/M, M, W/M, M, C)',
              '    return x.view(-1, H, W, C)                     # (B, H, W, C)',
              '',
              '',
              'def shift_mask(H, W, M, s):                       # máscara de SW-MSA, s = M // 2',
              '    img = torch.zeros(1, H, W, 1)                  # región de cada posición, en coordenadas YA desplazadas',
              '    cuts = (slice(0, -M), slice(-M, -s), slice(-s, None))   # 3 franjas por eje → 9 regiones',
              '    r = 0',
              '    for hs in cuts:',
              '        for ws in cuts:',
              '            img[:, hs, ws, :] = r',
              '            r += 1',
              '    reg = window_partition(img, M).squeeze(-1)     # (nW, M²): región de cada token de cada ventana',
              '    diff = reg[:, None, :] - reg[:, :, None]       # (nW, M², M²): ≠ 0 si las regiones difieren',
              '    return diff.masked_fill(diff != 0, -100.0)     # 0 o −100; se suma a QKᵀ/√d_h + B antes del softmax',
              '',
              '',
              'def sw_msa_skeleton(x, M, attn):                  # x: (B, H, W, C); attn: (B·nW, M², C), mask → mismo',
              '    B, H, W, C = x.shape',
              '    s = M // 2',
              '    x = torch.roll(x, shifts=(-s, -s), dims=(1, 2))           # cyclic shift',
              '    w = window_partition(x, M)',
              '    w = attn(w, shift_mask(H, W, M, s).to(x))                 # atención por ventana con la máscara',
              '    x = window_reverse(w, M, H, W)',
              '    return torch.roll(x, shifts=(s, s), dims=(1, 2))          # deshacer: signo opuesto',
            ].join('\n'), note: R`Comprobado con timm 1.0 y torch 2: para el stage 1 de Swin-T (H = W = ${qn('quantities.s1Res')}, M = ${qn('cfg.M')}, s = ${qn('quantities.s1Shift')}), <code>shift_mask</code> da ${qn('quantities.s1Windows')} ventanas, idéntica al <code>attn_mask</code> de timm, y solo 15 tienen algún −100: las de la última fila y la última columna de ventanas. <code>window_reverse(window_partition(x))</code> devuelve <code>x</code> exacto, y <code>sw_msa_skeleton</code> con la <code>WindowAttention</code> de un bloque de timm da la misma salida que el bloque de timm. Las regiones se etiquetan en coordenadas <b>ya desplazadas</b>: la máscara se arma sobre el mapa enrollado, que es el que se parte en ventanas.` },
          ] },
          { t: 'p', html: R`<b>Los bugs que busca el entrevistador:</b>` },
          { t: 'list', items: [
            R`<code>x.view(-1, M*M, C)</code> sin el <code>permute</code>: corre y da la forma correcta, pero cada "ventana" son 49 tokens seguidos de una misma fila de la imagen, no un cuadrado de 7×7. Silencioso.`,
            R`Olvidar <code>.contiguous()</code> después del <code>permute</code>: este sí falla, con un error de <code>view</code> (o usa <code>reshape</code>, que copia si hace falta).`,
            R`Calcular las regiones de la máscara sobre el mapa sin desplazar: la máscara queda corrida respecto de las ventanas que de verdad se atienden.`,
            R`Usar el mismo signo en el roll y en el unshift: no falla, pero el residual suma cada token con otro corrido 2·⌊M/2⌋ posiciones.`,
            R`Aplicar shift y máscara en un stage donde el mapa cabe en una ventana (el stage 4 de Swin-T): con timm o el código oficial, el shift tiene que ser 0.`,
          ] },
          { t: 'callout', kind: 'connect', html: R`<p>Repasa con las <a href="#flashcards">flashcards</a> de esta página y sigue en <a href="#practica">Práctica</a>. Después, <a href="#clip">CLIP</a>: dos encoders (uno es un ViT) entrenados para alinear imagen y texto.</p>` },
        ],
      },
    ],

    // ---------------------------------------------------------- flashcards
    flashcards: [
      { id: 'swin-01', kind: 'forma', q: 'Swin-T @ 224: formas de los cuatro mapas de stage.', a: R`${sh('s1-out')} → ${sh('s2-out')} → ${sh('s3-out')} → ${sh('s4-out')} (strides 4, 8, 16, 32).` },
      { id: 'swin-02', kind: 'forma', q: 'Swin-T @ 224: forma de la salida del patch embedding, como mapa y como secuencia.', a: R`Como mapa, ${sh('x-patch-grid')} (así lo guardan timm y el calculador); como secuencia, ${qn('tokens')}×${qn('cfg.C')}: N = ${qn('tokens')} tokens de 4×4 píxeles, cada uno de C = ${qn('cfg.C')}.` },
      { id: 'swin-03', kind: 'forma', q: 'Forma del tensor de ventanas en un bloque del stage 1 de Swin-T @ 224.', a: R`${sy('s1-b1-win')} = ${sh('s1-b1-win')}.` },
      { id: 'swin-04', kind: 'forma', q: 'Forma de Q por cabeza en el stage 1 de Swin-T @ 224.', a: R`${sy('s1-b1-q')} = ${sh('s1-b1-q')} (d<sub>h</sub> = 32).` },
      { id: 'swin-05', kind: 'forma', q: 'Forma de las puntuaciones de atención de un bloque del stage 1 de Swin-T @ 224.', a: R`${sy('s1-b1-scores')} = ${sh('s1-b1-scores')}: una matriz de 49×49 por ventana y cabeza.` },
      { id: 'swin-06', kind: 'forma', q: 'Primer patch merging de Swin-T: forma tras concatenar y tras reducir.', a: R`${sh('s1-out')} → ${sh('m1-concat')} → ${sh('m1-out')}.` },
      { id: 'swin-07', kind: 'formula', q: 'Ecuaciones 1 y 2 del paper: complejidad de MSA global vs W-MSA.', a: R`\(\Omega(\mathrm{MSA}) = 4hwC^2 + 2(hw)^2C\); \(\Omega(\text{W-MSA}) = 4hwC^2 + 2M^2hwC\), con h×w = alto×ancho del mapa de patches (no cabezas).` },
      { id: 'swin-08', kind: 'formula', q: 'Atención de Swin con relative position bias.', a: R`\(\mathrm{SoftMax}(QK^\top/\sqrt{d} + B)V\), con \(B\in\mathbb{R}^{M^2\times M^2}\) tomado de \(\hat{B}\in\mathbb{R}^{(2M-1)\times(2M-1)}\) por desplazamiento relativo.` },
      { id: 'swin-09', kind: 'formula', q: 'Patch merging.', a: R`Concatenar 2×2 vecinos (C → 4C) → LN(4C) → lineal 4C → 2C sin bias. Tokens ÷4, canales ×2.` },
      { id: 'swin-10', kind: 'formula', q: '¿Qué condición debe cumplir la resolución H para que Swin no necesite padding?', a: 'H múltiplo de 32·M (el mapa del stage 4, H/32, múltiplo de M): 224 = 32·7, 384 = 32·12.' },
      { id: 'swin-11', kind: 'conteo', q: 'Parámetros totales de Swin-T (cabeza de 1000 clases).', a: R`${qn('params.total')} (${qn('params.totalM')}). El paper redondea a 29M (Tabla 1(a)).` },
      { id: 'swin-12', kind: 'conteo', q: 'MACs de Swin-T @ 224 y cómo los reporta el paper.', a: R`${qn('macs.totalG')} MACs; la Tabla 1(a) los llama "4.5G FLOPs". En FLOPs reales, ${qn('flops.totalG')}.` },
      { id: 'swin-13', kind: 'conteo', q: '¿Cuántos parámetros tiene la tabla de relative position bias de un bloque del stage 1 de Swin-T?', a: '(2M−1)² × h = 169 × 3 = 507. Es un parámetro; el índice que la expande a 49×49 es un buffer.' },
      { id: 'swin-14', kind: 'conteo', q: 'Ventanas por stage en Swin-T @ 224.', a: R`${qn('quantities.s1Windows')}, ${qn('quantities.s2Windows')}, ${qn('quantities.s3Windows')}, ${qn('quantities.s4Windows')}: el stage 4 es una sola ventana.` },
      { id: 'swin-15', kind: 'conteo', q: 'Stage 1 de Swin-T: MACs de QKᵀ + A·V por bloque, en ventanas vs global.', a: R`${qn('metrics.s1ScoreMacs')} vs ${qn('metrics.s1GlobalScoreMacs')}: ×${qn('metrics.s1GlobalToWindow')} = N/M².` },
      { id: 'swin-16', kind: 'conteo', q: 'Duplicas la resolución de Swin con M fijo: ¿factor en tokens, MACs de atención y parámetros?', a: 'Tokens ×4, MACs de QKᵀ + A·V ≈ ×4 (lineal en N), parámetros ×1 (el bias depende de M, no de la resolución).' },
      { id: 'swin-17', kind: 'concepto', q: '¿Qué problema resuelven las shifted windows?', a: 'Con una partición fija, las ventanas no se comunican. Desplazar la partición ⌊M/2⌋ en bloques alternos hace que cada ventana nueva cubra partes de cuatro viejas: la información cruza los bordes.' },
      { id: 'swin-18', kind: 'concepto', q: '¿Por qué cyclic shift y no padding?', a: 'El roll mantiene el mismo número de ventanas de M×M (64 en el stage 1) y el mismo kernel batched; desplazar sin enrollar daría (⌈h/M⌉+1)² ventanas de tamaños distintos (81). Tabla 5: 755 vs 670 FPS.' },
      { id: 'swin-19', kind: 'concepto', q: '¿Por qué SW-MSA necesita una máscara?', a: 'El roll junta en una ventana tokens de lados opuestos de la imagen; la máscara (−100 entre regiones distintas, 9 regiones) evita que se atiendan entre sí.' },
      { id: 'swin-20', kind: 'concepto', q: 'Equivalencias Swin ↔ ResNet.', a: 'Patch embedding 4×4 s4 ≈ stem (stride 4); stages 1–4 ≈ C2–C5; patch merging ≈ conv stride 2 + doble de canales; ventana 7×7 ≈ campo receptivo local; MLP ≈ conv 1×1; LN+GAP+FC ≈ GAP+FC.' },
      { id: 'swin-21', kind: 'concepto', q: '¿Por qué Swin entra directo en un Mask R-CNN o UperNet?', a: 'Porque da mapas a strides 4, 8, 16, 32 como una ResNet; solo cambian los canales de entrada del FPN. COCO, Cascade Mask R-CNN: 46.3 → 50.5 AP box con R-50 → Swin-T (Tabla 2(a)).' },
      { id: 'swin-22', kind: 'concepto', q: 'Relative position bias vs position embedding absoluta de ViT.', a: 'El bias se suma a las puntuaciones y depende solo del desplazamiento relativo dentro de la ventana: invariante a traslación e independiente del tamaño de imagen. Supera a la absoluta: 81.3 vs 80.5 top-1, 50.5 vs 49.0 AP box (Tabla 4).' },
      { id: 'swin-23', kind: 'concepto', q: 'Receta de entrenamiento de Swin en ImageNet-1K (lo que se espera oír).', a: 'AdamW + warmup + cosine, weight decay 0.05, augmentation de DeiT (RandAugment, Mixup, CutMix) y stochastic depth que crece con el tamaño del modelo.' },
      { id: 'swin-24', kind: 'concepto', q: 'Swin V2: los tres cambios principales.', a: 'Res-post-norm, scaled cosine attention (cos/τ + B) y log-spaced continuous position bias; preentrenamiento SimMIM.' },
      { id: 'swin-25', kind: 'tradeoff', q: 'Swin vs ConvNeXt.', a: 'Rinden parecido a igual tamaño y receta (ConvNeXt-T 82.1 vs Swin-T 81.3, ConvNeXt Tabla 1). ConvNeXt es más simple de desplegar; Swin tiene pesos dependientes del contenido. Elige por checkpoint y despliegue.' },
      { id: 'swin-27', kind: 'trampa', q: '"Las ventanas desplazadas de Swin se solapan."', a: 'No: en cada bloque forman una partición sin solapamiento. Cambia dónde están los bordes entre un bloque y el siguiente.' },
      { id: 'swin-28', kind: 'trampa', q: '"La mitad de los bloques de Swin-T usan shift."', a: 'Cinco de 12: en el stage 4 (7×7 con M = 7) hay una sola ventana y el shift es 0 (implementación oficial y timm).' },
      { id: 'swin-29', kind: 'trampa', q: '"En Ω = 4hwC² + 2(hw)²C, h es el número de cabezas."', a: 'No: h×w es el tamaño del mapa de patches. Las cabezas no aparecen: QKᵀ cuesta N²C sin importar cuántas haya.' },
      { id: 'swin-30', kind: 'trampa', q: '"Swin-T es más rápido que DeiT-S porque tiene menos FLOPs."', a: 'No: 4.5G vs 4.6G "FLOPs" pero 755.2 vs 940.4 img/s (Tabla 1(a), V100). Particiones, rolls, máscaras y activaciones grandes son memory-bound.' },
      { id: 'swin-31', kind: 'trampa', q: '"El relative position bias es un buffer fijo."', a: 'La tabla B̂ ((2M−1)² × h) es un parámetro aprendido; lo que es buffer es el índice que la expande a M²×M² (y la máscara del shift).' },
      { id: 'swin-32', kind: 'concepto', q: '¿Por qué Swin usa ventanas sin solapamiento + shift y no una ventana deslizante por token?', a: 'Mismos FLOPs, pero en la deslizante cada consulta tiene sus propias claves (un gather por token). Sin solapamiento, las 49 consultas de una ventana comparten las 49 claves: una matmul densa batched. Tabla 5 (Swin-T, V100): 755 FPS con shifted windows vs 488 con un kernel deslizante propio.' },
      { id: 'swin-33', kind: 'tradeoff', q: 'Hoy: ¿Swin, ViT plano o CNN para (a) detección en tiempo real en un Jetson, (b) segmentación a 1024 px con pocas etiquetas, (c) el encoder de un VLM o de una política de robot?', a: '(a) CNN: fusiona y cuantiza bien. (b) Jerárquico (Swin o ConvNeXt) si hay checkpoints de detección, o un ViT plano autosupervisado fuerte con ViTDet. (c) ViT plano (SigLIP, CLIP, DINOv2): checkpoints alineados y secuencia plana de tokens.' },
      { id: 'swin-34', kind: 'concepto', q: '¿Qué hace ViTDet para usar un ViT plano como backbone de detección?', a: 'Atención en ventanas (sin shift) en la mayoría de los bloques, unos pocos bloques de atención global repartidos por la red, y una pirámide simple construida solo desde el último mapa (stride 16) con deconvs y pooling, sin FPN jerárquico.' },
      { id: 'swin-35', kind: 'conteo', q: 'Stochastic depth de Swin-T, Swin-S y Swin-B en ImageNet-1K.', a: '0.2, 0.3 y 0.5 (Apéndice A2.1): más regularización cuanto más grande el modelo.' },
      { id: 'swin-36', kind: 'conteo', q: 'Swin en ImageNet-1K: épocas, warmup, batch y learning rate.', a: '300 épocas con cosine decay, 20 épocas de warmup lineal, batch 1024, lr inicial 0.001 (§4.1).' },
      { id: 'swin-37', kind: 'trampa', q: '"Swin cuesta lineal en la resolución."', a: 'Lineal en el número de tokens (H·W) para M fijo, o sea cuadrático en el lado: 224 → 448 da ×4. El precio es un alcance fijo de 7×7 tokens por bloque; ViTDet intercala bloques globales por eso.' },
      { id: 'swin-38', kind: 'trampa', q: '"Para partir en ventanas basta con x.view(-1, M*M, C)."', a: 'No: corre y da la forma correcta, pero cada "ventana" son 49 tokens seguidos de una fila. Hay que hacer view a (B, H/M, M, W/M, M, C), permute(0, 1, 3, 2, 4, 5) y contiguous() antes del view final.' },
      { id: 'swin-39', kind: 'concepto', q: '¿Por qué la máscara de Swin usa −100 y no −∞?', a: 'El código oficial no lo explica: e⁻¹⁰⁰ ≈ 0 tras el softmax, así que el efecto es el mismo, sin aritmética con infinitos. −∞ también funcionaría sin NaN, porque cada token comparte región al menos consigo mismo: ninguna fila queda enmascarada entera.' },
    ],

    // ---------------------------------------------------------- glosario
    glossary: [
      { en: 'window attention (W-MSA)', es: 'atención por ventanas', def: 'Self-attention calculada por separado dentro de ventanas de M×M tokens que no se solapan; costo lineal en el número de tokens para M fijo.', say: 'Window attention makes the quadratic term linear in the number of tokens for a fixed window size.' },
      { en: 'shifted window (SW-MSA)', es: 'ventana desplazada', def: 'Partición en ventanas desplazada ⌊M/2⌋ tokens respecto del bloque anterior, para que la información cruce los bordes de las ventanas.', say: 'Every other block shifts the window partition by half a window.' },
      { en: 'cyclic shift', es: 'desplazamiento cíclico', def: 'Enrollar el mapa de features (torch.roll) antes de partir en ventanas, para mantener el mismo número de ventanas de M×M al desplazar la partición.', say: 'The cyclic shift keeps the number of windows unchanged, so the batched kernel stays the same.' },
      { en: 'attention mask (Swin)', es: 'máscara de atención del desplazamiento', def: 'Tensor aditivo (0 o −100) que impide atender entre tokens que el desplazamiento cíclico juntó en una ventana sin ser vecinos en la imagen.', say: 'The mask blocks attention between sub-windows that the roll brought together.' },
      { en: 'relative position bias', es: 'sesgo de posición relativa', def: 'Escalar aprendido por cabeza para cada desplazamiento relativo (2M−1)² dentro de la ventana, sumado a QKᵀ antes del softmax.', say: 'Swin adds a learned relative position bias to the attention logits instead of absolute position embeddings.' },
      { en: 'patch merging', es: 'fusión de parches', def: 'Downsampling de Swin: concatenar 2×2 tokens vecinos (4C), LayerNorm y lineal a 2C sin bias. Resolución ÷2, canales ×2.', say: 'Patch merging halves the resolution and doubles the channels, like a strided convolution.' },
      { en: 'linear embedding', es: 'embedding lineal', def: 'En Swin, la proyección de cada patch de 4×4×3 = 48 valores a C dimensiones (una conv 4×4 stride 4), seguida de LayerNorm.', say: 'Patch partition plus linear embedding is a 4-by-4 stride-4 convolution.' },
      { en: 'stage', es: 'etapa', def: 'Grupo de bloques que trabaja a una resolución fija; entre stages se reduce la resolución. Swin y ResNet tienen 4, a strides 4, 8, 16 y 32.', say: 'Swin has four stages at strides 4, 8, 16 and 32, just like a ResNet.' },
      { en: 'feature pyramid', es: 'pirámide de features', def: 'Conjunto de mapas a varias escalas (C2–C5) que consumen FPN, Mask R-CNN o UperNet para detectar objetos de distintos tamaños.', say: 'Swin outputs a feature pyramid that plugs directly into an FPN.' },
      { en: 'UperNet', es: 'UperNet', def: 'Decoder de segmentación semántica sobre una pirámide de features (PPM + FPN); el paper de Swin lo usa en ADE20K.', say: 'For ADE20K the Swin paper uses UperNet on top of the four stage outputs.' },
      { en: 'res-post-norm', es: 'post-normalización residual', def: 'Cambio de Swin V2: la LayerNorm se aplica a la salida de cada rama residual antes de sumarla, para que la amplitud de las activaciones no crezca con la profundidad.', say: 'Swin V2 moves the LayerNorm to the end of each residual branch to stabilize very large models.' },
      { en: 'scaled cosine attention', es: 'atención coseno escalada', def: 'Swin V2: similitud cos(q, k)/τ + B en lugar de q·k/√d, con τ aprendido; evita que unas pocas parejas dominen la atención.', say: 'Scaled cosine attention replaces the dot product with a cosine similarity divided by a learned temperature.' },
    ],
  });
})(typeof window !== 'undefined' ? window : globalThis);
